{
  "name": "codetutor-frontend",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "preview": "vite preview",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@monaco-editor/react": "4.7.0",
    "monaco-editor": "0.57.0",
    "react": "19.3.1",
    "react-dom": "19.3.1"
  },
  "devDependencies": {
    "@types/react": "19.2.2",
    "@types/react-dom": "19.2.1",
    "@vitejs/plugin-react": "6.1.2",
    "typescript": "5.9.3",
    "vite": "8.3.5"
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// The CodeTutor frontend is rooted here (frontend/public) to match the
// existing src/ layout. Static assets, if any, can live in ./static.
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
  },
});

// Shared types for CodeTutor.

/** Programming languages CodeTutor supports. */
export type Language = "java" | "python" | "c";

/** Maps a CodeTutor language to the Monaco editor language id. */
export const MONACO_LANGUAGE_ID: Record<Language, string> = {
  java: "java",
  python: "python",
  c: "c",
};

/** Human-readable labels for the language selector. */
export const LANGUAGE_LABELS: Record<Language, string> = {
  java: "Java",
  python: "Python",
  c: "C",
};

/** Starter snippets shown when the user switches language. */
export const STARTER_CODE: Record<Language, string> = {
  java: `public class Main {
    public static void main(String[] args) {
        System.out.println("Hello, CodeTutor!");
    }
}
`,
  python: `def main():
    print("Hello, CodeTutor!")


if __name__ == "__main__":
    main()
`,
  c: `#include <stdio.h>

int main(void) {
    printf("Hello, CodeTutor!\\n");
    return 0;
}
`,
};

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./styles.css";

const rootEl = document.getElementById("root");
if (!rootEl) {
  throw new Error("Root element #root not found");
}

createRoot(rootEl).render(
  <StrictMode>
    <App />
  </StrictMode>
);

import { useRef } from "react";
import Editor, { type OnMount } from "@monaco-editor/react";
import type { editor } from "monaco-editor";
import {
  type Language,
  LANGUAGE_LABELS,
  MONACO_LANGUAGE_ID,
} from "../../types";

export interface CodeEditorProps {
  /** Current source code (controlled value). */
  value: string;
  /** Active programming language. */
  language: Language;
  /** Called whenever the editor content changes. */
  onChange: (value: string) => void;
  /** Called when the user picks a different language. */
  onLanguageChange: (language: Language) => void;
  /** Called when the user asks to run/analyze the code. */
  onRun?: () => void;
  /** Disables the run button (e.g. while a run is in flight). */
  running?: boolean;
}

const LANGUAGES: Language[] = ["java", "python", "c"];

/**
 * The left half of CodeTutor: a Monaco-based code editor with a language
 * selector and a run button. Kept presentational and controlled so the parent
 * owns the source + language state and can feed it to the visualizer/tutor.
 */
export default function CodeEditor({
  value,
  language,
  onChange,
  onLanguageChange,
  onRun,
  running = false,
}: CodeEditorProps) {
  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null);

  const handleMount: OnMount = (editorInstance) => {
    editorRef.current = editorInstance;
    editorInstance.focus();
  };

  return (
    <div className="code-editor">
      <div className="code-editor__toolbar">
        <label className="code-editor__lang">
          <span>Language</span>
          <select
            value={language}
            onChange={(e) => onLanguageChange(e.target.value as Language)}
          >
            {LANGUAGES.map((lang) => (
              <option key={lang} value={lang}>
                {LANGUAGE_LABELS[lang]}
              </option>
            ))}
          </select>
        </label>

        <button
          type="button"
          className="code-editor__run"
          onClick={onRun}
          disabled={running || !onRun}
        >
          {running ? "Running..." : "Run"}
        </button>
      </div>

      <div className="code-editor__surface">
        <Editor
          height="100%"
          theme="vs-dark"
          language={MONACO_LANGUAGE_ID[language]}
          value={value}
          onMount={handleMount}
          onChange={(next) => onChange(next ?? "")}
          options={{
            fontSize: 14,
            minimap: { enabled: false },
            scrollBeyondLastLine: false,
            automaticLayout: true,
            tabSize: 4,
            smoothScrolling: true,
            renderWhitespace: "selection",
          }}
        />
      </div>
    </div>
  );
}

import type { Language } from "../../types";

export interface VisualizationPanelProps {
  /** Source currently in the editor (what we would visualize). */
  code: string;
  /** Active language, in case the visualizer renders differently per language. */
  language: Language;
}

/**
 * The right half of CodeTutor: the visualizer. This is where box diagrams,
 * trees, and other illustrations of program behavior will be rendered.
 *
 * Placeholder for now — it echoes basic info so the layout is wired up and
 * ready for the real visualization engine.
 */
export default function VisualizationPanel({
  code,
  language,
}: VisualizationPanelProps) {
  const lineCount = code.split("\n").length;

  return (
    <div className="panel visualization-panel">
      <h2 className="panel__title">Visualizer</h2>
      <p className="panel__hint">
        Box diagrams and trees illustrating your {language} program will appear
        here.
      </p>
      <div className="visualization-panel__placeholder">
        <p>Nothing to visualize yet.</p>
        <p className="panel__meta">{lineCount} line(s) of code</p>
      </div>
    </div>
  );
}

export interface TutorPanelProps {
  /** The latest guiding question/hint from the tutor, if any. */
  question?: string;
}

/**
 * The tutor surface: when CodeTutor detects a likely logic error, it poses a
 * question here that nudges the learner toward the correct solution.
 *
 * Placeholder for now — renders whatever question it is given.
 */
export default function TutorPanel({ question }: TutorPanelProps) {
  return (
    <div className="panel tutor-panel">
      <h2 className="panel__title">Tutor</h2>
      {question ? (
        <p className="tutor-panel__question">{question}</p>
      ) : (
        <p className="panel__hint">
          Run your code and I'll ask guiding questions when something looks off.
        </p>
      )}
    </div>
  );
}

export type AlertSeverity = "error" | "warning" | "info";

export interface Alert {
  id: string;
  severity: AlertSeverity;
  message: string;
  /** Optional 1-based line number the alert refers to. */
  line?: number;
}

export interface AlertPanelProps {
  alerts: Alert[];
}

/**
 * Surfaces problems detected in the user's code (compile errors, and
 * especially the logic errors CodeTutor is built to catch).
 *
 * Placeholder rendering for now.
 */
export default function AlertPanel({ alerts }: AlertPanelProps) {
  if (alerts.length === 0) {
    return (
      <div className="panel alert-panel">
        <h2 className="panel__title">Problems</h2>
        <p className="panel__hint">No problems detected.</p>
      </div>
    );
  }

  return (
    <div className="panel alert-panel">
      <h2 className="panel__title">Problems</h2>
      <ul className="alert-panel__list">
        {alerts.map((alert) => (
          <li key={alert.id} className={`alert alert--${alert.severity}`}>
            {alert.line !== undefined && (
              <span className="alert__line">Line {alert.line}</span>
            )}
            <span className="alert__message">{alert.message}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import CodeEditor from "../editor/CodeEditor";
import VisualizationPanel from "../visualization/VisualizationPanel";
import TutorPanel from "../tutor/TutorPanel";
import AlertPanel, { type Alert } from "../alerts/AlertPanel";
import type { Language } from "../../types";

export interface WorkspaceProps {
  code: string;
  language: Language;
  alerts: Alert[];
  tutorQuestion?: string;
  running?: boolean;
  onCodeChange: (value: string) => void;
  onLanguageChange: (language: Language) => void;
  onRun?: () => void;
}

/**
 * Top-level CodeTutor layout: editor on the left half, visualizer + tutor +
 * problems on the right half.
 */
export default function Workspace({
  code,
  language,
  alerts,
  tutorQuestion,
  running,
  onCodeChange,
  onLanguageChange,
  onRun,
}: WorkspaceProps) {
  return (
    <div className="workspace">
      <section className="workspace__left">
        <CodeEditor
          value={code}
          language={language}
          onChange={onCodeChange}
          onLanguageChange={onLanguageChange}
          onRun={onRun}
          running={running}
        />
      </section>

      <section className="workspace__right">
        <VisualizationPanel code={code} language={language} />
        <TutorPanel question={tutorQuestion} />
        <AlertPanel alerts={alerts} />
      </section>
    </div>
  );
}

import { useState } from "react";
import Workspace from "./components/layout/Workspace";
import type { Alert } from "./components/alerts/AlertPanel";
import { type Language, STARTER_CODE } from "./types";

export default function App() {
  const [language, setLanguage] = useState<Language>("python");
  const [code, setCode] = useState<string>(STARTER_CODE.python);
  const [alerts] = useState<Alert[]>([]);
  const [tutorQuestion] = useState<string | undefined>(undefined);
  const [running, setRunning] = useState(false);

  const handleLanguageChange = (next: Language) => {
    setLanguage(next);
    // Swap in the starter snippet for the new language.
    setCode(STARTER_CODE[next]);
  };

  const handleRun = () => {
    // Placeholder: this will call the Rust backend to analyze/run the code.
    setRunning(true);
    window.setTimeout(() => setRunning(false), 400);
  };

  return (
    <div className="app">
      <header className="app__header">
        <h1 className="app__brand">CodeTutor</h1>
        <p className="app__tagline">
          Write code, watch it come to life, and learn as you go.
        </p>
      </header>

      <main className="app__main">
        <Workspace
          code={code}
          language={language}
          alerts={alerts}
          tutorQuestion={tutorQuestion}
          running={running}
          onCodeChange={setCode}
          onLanguageChange={handleLanguageChange}
          onRun={handleRun}
        />
      </main>
    </div>
  );
}

:root {
  --bg: #1e1e1e;
  --panel-bg: #252526;
  --border: #333;
  --text: #e4e4e4;
  --muted: #9a9a9a;
  --accent: #0e8adb;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.app__header {
  padding: 0.6rem 1rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: baseline;
  gap: 1rem;
}

.app__brand {
  margin: 0;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
}

.app__tagline {
  margin: 0;
  color: var(--muted);
  font-size: 0.85rem;
}

.app__main {
  flex: 1;
  min-height: 0;
}

/* Split the screen in half: editor left, analysis right. */
.workspace {
  display: grid;
  grid-template-columns: 1fr 1fr;
  height: 100%;
  min-height: 0;
}

.workspace__left {
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--border);
}

.workspace__right {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

/* Editor */
.code-editor {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.code-editor__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--border);
  background: var(--panel-bg);
}

.code-editor__lang {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.code-editor__lang select {
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.25rem 0.5rem;
}

.code-editor__run {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 4px;
  padding: 0.35rem 1rem;
  font-size: 0.85rem;
  cursor: pointer;
}

.code-editor__run:disabled {
  opacity: 0.6;
  cursor: default;
}

.code-editor__surface {
  flex: 1;
  min-height: 0;
}

/* Panels on the right */
.panel {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border);
}

.panel__title {
  margin: 0 0 0.5rem;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.panel__hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.panel__meta {
  color: var(--muted);
  font-size: 0.8rem;
}

.visualization-panel {
  flex: 1;
  min-height: 200px;
}

.visualization-panel__placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  height: 100%;
  min-height: 160px;
  border: 1px dashed var(--border);
  border-radius: 6px;
  color: var(--muted);
}

.tutor-panel__question {
  margin: 0;
  padding: 0.6rem 0.75rem;
  background: rgba(14, 138, 219, 0.12);
  border-left: 3px solid var(--accent);
  border-radius: 4px;
}

.alert-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.alert {
  display: flex;
  gap: 0.5rem;
  padding: 0.4rem 0.6rem;
  border-radius: 4px;
  font-size: 0.88rem;
}

.alert--error {
  background: rgba(220, 70, 70, 0.14);
}

.alert--warning {
  background: rgba(220, 180, 70, 0.14);
}

.alert--info {
  background: rgba(70, 150, 220, 0.14);
}

.alert__line {
  color: var(--muted);
  flex-shrink: 0;
}

// Trace data model for the CodeTutor visualizer.
//
// This is the contract between the (future) Rust backend and the frontend.
// The backend interprets the user's Java/Python/C program step by step and
// emits an ExecutionTrace: an ordered list of ProgramState snapshots, one per
// executed step. The frontend is a pure renderer of this model and does not
// care how the trace was produced.
//
// The central idea is distinguishing VALUE semantics from REFERENCE semantics:
//   - A `primitive` value lives inline in a variable box (x -> [ 3 ]).
//   - A `ref` value is a pointer into the heap; the box holds an arrow that
//     points at a heap object (values -> [ ][ ][ ] ... -> objects).

/** A pointer to an object living in the heap. Null ref models null/None. */
export interface RefValue {
  kind: "ref";
  /** Heap object id this reference points at, or null for null/None. */
  target: HeapId | null;
}

/** An inline, copied-by-value scalar (int, double, char, bool, etc.). */
export interface PrimitiveValue {
  kind: "primitive";
  /** Display text for the value, e.g. "3", "true", "'a'", "3.14". */
  display: string;
  /** Optional finer type hint for styling, e.g. "int", "char", "bool". */
  typeName?: string;
}

/** A value stored in a variable slot or an object field / array cell. */
export type Value = PrimitiveValue | RefValue;

/** Stable identifier for a heap-allocated object. */
export type HeapId = string;

/** A named binding inside a stack frame (a local variable or parameter). */
export interface Variable {
  name: string;
  value: Value;
  /** Static/declared type if known, e.g. "int[]", "Node", "String". */
  declaredType?: string;
}

/** One function/method activation on the call stack. */
export interface StackFrame {
  /** Stable id so the renderer can key frames across steps. */
  id: string;
  /** Function or method name, e.g. "main", "fib". */
  functionName: string;
  /** Locals + parameters visible in this frame. */
  variables: Variable[];
  /** True for the currently executing (top) frame. */
  isActive?: boolean;
}

/** An array object in the heap (contiguous indexed cells). */
export interface ArrayObject {
  kind: "array";
  id: HeapId;
  /** Element type if known, e.g. "int", "Node". */
  elementType?: string;
  /** Cells in index order; each is a value (primitive or ref). */
  elements: Value[];
}

/** A record/struct/class instance in the heap (named fields). */
export interface StructObject {
  kind: "struct";
  id: HeapId;
  /** Class/struct name shown as the object label, e.g. "Node", "o1". */
  typeName: string;
  fields: Variable[];
}

/** Anything that can live in the heap. */
export type HeapObject = ArrayObject | StructObject;

/** A single snapshot of the program at one execution step. */
export interface ProgramState {
  /** 0-based index of this step within the trace. */
  step: number;
  /** 1-based source line about to execute / just executed, if known. */
  line?: number;
  /** Call stack, outermost frame first, active frame last. */
  stack: StackFrame[];
  /** Heap objects keyed by id. */
  heap: Record<HeapId, HeapObject>;
  /** Optional human note for this step, e.g. "i = 1, swapped a and b". */
  note?: string;
  /** Standard output produced so far, if the backend tracks it. */
  stdout?: string;
}

/** The full execution trace: an ordered list of states to scrub through. */
export interface ExecutionTrace {
  states: ProgramState[];
}

// ---- Type guards (handy for the renderer) --------------------------------

export function isRef(v: Value): v is RefValue {
  return v.kind === "ref";
}

export function isPrimitive(v: Value): v is PrimitiveValue {
  return v.kind === "primitive";
}

export function isArray(o: HeapObject): o is ArrayObject {
  return o.kind === "array";
}

export function isStruct(o: HeapObject): o is StructObject {
  return o.kind === "struct";
}

import type {
  ExecutionTrace,
  HeapObject,
  ProgramState,
  Value,
} from "./trace";

// A hand-built sample trace used to develop and demo the visualizer before the
// Rust backend emits real traces. It models a small program:
//
//   int[] values = {4, 5, 6};
//   Node[] nodes = {o1, o2, o3};
//   int x = 3;
//   for (int i = 0; i < values.length - 1; i++) {
//       if (values[i] > values[i + 1]) { swap(values, i, i + 1); }
//   }
//
// It exercises: a primitive variable (value semantics), an int array (value
// cells), an array of object references (reference semantics), the heap/stack
// split, and changing state across loop iterations.

const prim = (display: string, typeName?: string): Value => ({
  kind: "primitive",
  display,
  typeName,
});

const ref = (target: string | null): Value => ({ kind: "ref", target });

/** Build the heap for a given ordering of the int array cells. */
function makeHeap(cells: number[]): Record<string, HeapObject> {
  return {
    arr_values: {
      kind: "array",
      id: "arr_values",
      elementType: "int",
      elements: cells.map((n) => prim(String(n), "int")),
    },
    arr_nodes: {
      kind: "array",
      id: "arr_nodes",
      elementType: "Node",
      elements: [ref("o1"), ref("o2"), ref("o3")],
    },
    o1: {
      kind: "struct",
      id: "o1",
      typeName: "Node",
      fields: [{ name: "data", value: prim("4", "int") }],
    },
    o2: {
      kind: "struct",
      id: "o2",
      typeName: "Node",
      fields: [{ name: "data", value: prim("5", "int") }],
    },
    o3: {
      kind: "struct",
      id: "o3",
      typeName: "Node",
      fields: [{ name: "data", value: prim("6", "int") }],
    },
  };
}

function frame(i: number | null, cells: number[]): ProgramState["stack"] {
  const vars = [
    {
      name: "values",
      declaredType: "int[]",
      value: ref("arr_values"),
    },
    {
      name: "nodes",
      declaredType: "Node[]",
      value: ref("arr_nodes"),
    },
    { name: "x", declaredType: "int", value: prim("3", "int") },
  ];
  if (i !== null) {
    vars.push({ name: "i", declaredType: "int", value: prim(String(i), "int") });
  }
  void cells;
  return [
    {
      id: "frame_main",
      functionName: "main",
      isActive: true,
      variables: vars,
    },
  ];
}

export const SAMPLE_TRACE: ExecutionTrace = {
  states: [
    {
      step: 0,
      line: 1,
      note: "Declared values = [4, 5, 6], x = 3.",
      stack: frame(null, [4, 5, 6]),
      heap: makeHeap([4, 5, 6]),
    },
    {
      step: 1,
      line: 5,
      note: "Enter loop, i = 0. Compare values[0]=4 and values[1]=5.",
      stack: frame(0, [4, 5, 6]),
      heap: makeHeap([4, 5, 6]),
    },
    {
      step: 2,
      line: 5,
      note: "4 < 5, no swap. i = 1. Compare values[1]=5 and values[2]=6.",
      stack: frame(1, [4, 5, 6]),
      heap: makeHeap([4, 5, 6]),
    },
    {
      step: 3,
      line: 6,
      note: "5 < 6, no swap. Array already sorted; loop ends.",
      stack: frame(2, [4, 5, 6]),
      heap: makeHeap([4, 5, 6]),
    },
  ],
};

import { type Value, isRef } from "./trace";

export interface ValueCellProps {
  value: Value;
  /**
   * Registers the DOM node for a reference cell so the arrow layer can draw a
   * line from this cell to its heap target. Keyed by a connector id.
   */
  registerAnchor?: (id: string, el: HTMLElement | null) => void;
  /** Connector id used when this cell holds a reference. */
  anchorId?: string;
}

/**
 * A single boxed slot. Primitives show their value inline (value semantics);
 * references show a dot/arrow source that the arrow layer connects to the heap
 * (reference semantics). A null reference is drawn as a slashed empty box.
 */
export default function ValueCell({
  value,
  registerAnchor,
  anchorId,
}: ValueCellProps) {
  if (isRef(value)) {
    const isNull = value.target === null;
    return (
      <span
        className={`cell cell--ref${isNull ? " cell--null" : ""}`}
        ref={(el) => {
          if (registerAnchor && anchorId) registerAnchor(anchorId, el);
        }}
      >
        {isNull ? "∅" : <span className="cell__dot" aria-label="reference" />}
      </span>
    );
  }

  return (
    <span className="cell cell--primitive" title={value.typeName}>
      {value.display}
    </span>
  );
}

import { type HeapObject, isArray } from "./trace";
import ValueCell from "./ValueCell";

export interface HeapObjectViewProps {
  object: HeapObject;
  /** Registers this object's box so arrows can target it. */
  registerAnchor: (id: string, el: HTMLElement | null) => void;
  /** Registers a reference cell inside this object (e.g. array-of-objects). */
  registerCellAnchor: (id: string, el: HTMLElement | null) => void;
}

/** The anchor id of an object's own box (arrow targets point here). */
export function objectAnchorId(id: string): string {
  return `obj:${id}`;
}

/** The anchor id of the i-th reference cell inside an array object. */
export function cellAnchorId(objId: string, index: number): string {
  return `cell:${objId}:${index}`;
}

/**
 * Renders one heap object. Arrays show indexed cells in a row; a cell holding a
 * reference becomes the source of a down-arrow to another object. Structs show
 * a titled box with one row per field.
 */
export default function HeapObjectView({
  object,
  registerAnchor,
  registerCellAnchor,
}: HeapObjectViewProps) {
  if (isArray(object)) {
    return (
      <div
        className="heap-object heap-object--array"
        ref={(el) => registerAnchor(objectAnchorId(object.id), el)}
      >
        <div className="heap-object__cells">
          {object.elements.map((el, i) => (
            <div className="array-cell" key={i}>
              <span className="array-cell__index">{i}</span>
              <ValueCell
                value={el}
                registerAnchor={registerCellAnchor}
                anchorId={cellAnchorId(object.id, i)}
              />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div
      className="heap-object heap-object--struct"
      ref={(el) => registerAnchor(objectAnchorId(object.id), el)}
    >
      <div className="heap-object__title">{object.typeName}</div>
      <div className="heap-object__fields">
        {object.fields.map((field) => (
          <div className="struct-field" key={field.name}>
            <span className="struct-field__name">{field.name}</span>
            <ValueCell
              value={field.value}
              registerAnchor={registerCellAnchor}
              anchorId={cellAnchorId(object.id, 0) + ":" + field.name}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

import { type StackFrame, isRef } from "./trace";
import ValueCell from "./ValueCell";

export interface StackFrameViewProps {
  frame: StackFrame;
  registerCellAnchor: (id: string, el: HTMLElement | null) => void;
}

/** Anchor id for a variable slot that holds a reference. */
export function variableAnchorId(frameId: string, varName: string): string {
  return `var:${frameId}:${varName}`;
}

/**
 * One stack frame: a titled box with a row per variable. Primitive variables
 * read like `x -> [ 3 ]`; reference variables like `values -> [•]` with an
 * arrow (drawn by the overlay) to the heap object.
 */
export default function StackFrameView({
  frame,
  registerCellAnchor,
}: StackFrameViewProps) {
  return (
    <div className={`frame${frame.isActive ? " frame--active" : ""}`}>
      <div className="frame__title">{frame.functionName}</div>
      <div className="frame__vars">
        {frame.variables.map((v) => (
          <div className="var-row" key={v.name}>
            <span className="var-row__name" title={v.declaredType}>
              {v.name}
            </span>
            <span className="var-row__arrow">→</span>
            <ValueCell
              value={v.value}
              registerAnchor={registerCellAnchor}
              anchorId={
                isRef(v.value)
                  ? variableAnchorId(frame.id, v.name)
                  : undefined
              }
            />
          </div>
        ))}
      </div>
    </div>
  );
}

import { useLayoutEffect, useState } from "react";

export interface Connection {
  from: string;
  to: string;
}

export interface ArrowLayerProps {
  /** Container the arrows are drawn over; coordinates are relative to it. */
  containerRef: React.RefObject<HTMLElement | null>;
  /** Map of anchor id -> DOM element, populated by the box components. */
  anchors: Map<string, HTMLElement>;
  /** Source -> target connections to draw. */
  connections: Connection[];
  /** Bump this to force a re-measure (e.g. when the step changes). */
  revision: number;
}

interface Segment {
  key: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  /** Mostly-vertical arrows (array cell -> object below) curve differently. */
  vertical: boolean;
}

function centerRight(r: DOMRect, c: DOMRect) {
  return { x: r.right - c.left, y: r.top - c.top + r.height / 2 };
}
function centerBottom(r: DOMRect, c: DOMRect) {
  return { x: r.left - c.left + r.width / 2, y: r.bottom - c.top };
}
function centerTop(r: DOMRect, c: DOMRect) {
  return { x: r.left - c.left + r.width / 2, y: r.top - c.top };
}
function centerLeft(r: DOMRect, c: DOMRect) {
  return { x: r.left - c.left, y: r.top - c.top + r.height / 2 };
}

/**
 * SVG overlay that draws arrows between anchored boxes. It measures element
 * rects on layout (and on container resize), so arrows follow the boxes.
 * Variable/array-cell -> object arrows leave from the right or bottom of the
 * source and enter the left or top of the target, whichever reads cleaner.
 */
export default function ArrowLayer({
  containerRef,
  anchors,
  connections,
  revision,
}: ArrowLayerProps) {
  const [segments, setSegments] = useState<Segment[]>([]);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const measure = () => {
      const c = container.getBoundingClientRect();
      const next: Segment[] = [];
      for (const conn of connections) {
        const fromEl = anchors.get(conn.from);
        const toEl = anchors.get(conn.to);
        if (!fromEl || !toEl) continue;
        const fr = fromEl.getBoundingClientRect();
        const tr = toEl.getBoundingClientRect();

        // Decide orientation: if the target sits mostly below the source,
        // draw a vertical arrow (the array-of-objects "|  V" pattern);
        // otherwise draw a horizontal one ("values -> [ ]").
        const vertical = tr.top - fr.bottom > -4 && Math.abs(
          (tr.left + tr.width / 2) - (fr.left + fr.width / 2)
        ) < Math.max(fr.width, tr.width) * 2;

        const start = vertical ? centerBottom(fr, c) : centerRight(fr, c);
        const end = vertical ? centerTop(tr, c) : centerLeft(tr, c);

        next.push({
          key: `${conn.from}->${conn.to}`,
          x1: start.x,
          y1: start.y,
          x2: end.x,
          y2: end.y,
          vertical,
        });
      }
      setSegments(next);
    };

    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(container);
    window.addEventListener("resize", measure);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
    // revision forces re-measure when the step/data changes.
  }, [containerRef, anchors, connections, revision]);

  return (
    <svg className="arrow-layer" aria-hidden="true">
      <defs>
        <marker
          id="arrowhead"
          markerWidth="8"
          markerHeight="8"
          refX="6"
          refY="3"
          orient="auto"
        >
          <path d="M0,0 L6,3 L0,6 Z" className="arrow-layer__head" />
        </marker>
      </defs>
      {segments.map((s) => {
        // Smooth cubic path; control points depend on orientation.
        const d = s.vertical
          ? `M ${s.x1},${s.y1} C ${s.x1},${(s.y1 + s.y2) / 2} ${s.x2},${
              (s.y1 + s.y2) / 2
            } ${s.x2},${s.y2}`
          : `M ${s.x1},${s.y1} C ${(s.x1 + s.x2) / 2},${s.y1} ${
              (s.x1 + s.x2) / 2
            },${s.y2} ${s.x2},${s.y2}`;
        return (
          <path
            key={s.key}
            d={d}
            className="arrow-layer__path"
            markerEnd="url(#arrowhead)"
          />
        );
      })}
    </svg>
  );
}

import { useMemo, useRef, useState } from "react";
import type { Language } from "../../types";
import {
  type ExecutionTrace,
  type ProgramState,
  isArray,
  isRef,
} from "./trace";
import { SAMPLE_TRACE } from "./sampleTrace";
import StackFrameView, { variableAnchorId } from "./StackFrameView";
import HeapObjectView, {
  cellAnchorId,
  objectAnchorId,
} from "./HeapObjectView";
import ArrowLayer, { type Connection } from "./ArrowLayer";

export interface VisualizationPanelProps {
  /** Source currently in the editor (unused until the backend wires up). */
  code: string;
  /** Active language. */
  language: Language;
  /**
   * Execution trace to visualize. Defaults to a built-in sample so the panel
   * is demoable before the Rust backend emits real traces.
   */
  trace?: ExecutionTrace;
}

/** Derive all arrows (source anchor -> target object) for one state. */
function connectionsFor(state: ProgramState): Connection[] {
  const conns: Connection[] = [];

  // Reference variables in each stack frame -> their heap object.
  for (const frame of state.stack) {
    for (const v of frame.variables) {
      if (isRef(v.value) && v.value.target) {
        conns.push({
          from: variableAnchorId(frame.id, v.name),
          to: objectAnchorId(v.value.target),
        });
      }
    }
  }

  // Reference cells inside array objects -> the objects they point at.
  for (const obj of Object.values(state.heap)) {
    if (isArray(obj)) {
      obj.elements.forEach((el, i) => {
        if (isRef(el) && el.target) {
          conns.push({
            from: cellAnchorId(obj.id, i),
            to: objectAnchorId(el.target),
          });
        }
      });
    }
  }

  return conns;
}

/**
 * The right half of CodeTutor: a box/arrow visualizer. It renders one program
 * state (stack frames + heap objects), drawing arrows for reference semantics,
 * and lets you scrub through the trace to watch state change per loop
 * iteration.
 */
export default function VisualizationPanel({
  language,
  trace = SAMPLE_TRACE,
}: VisualizationPanelProps) {
  const [step, setStep] = useState(0);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const anchorsRef = useRef<Map<string, HTMLElement>>(new Map());
  // Bump to force the arrow layer to re-measure after each render.
  const [revision, setRevision] = useState(0);

  const clampedStep = Math.min(step, trace.states.length - 1);
  const state = trace.states[clampedStep];

  const registerAnchor = (id: string, el: HTMLElement | null) => {
    if (el) anchorsRef.current.set(id, el);
    else anchorsRef.current.delete(id);
  };

  const connections = useMemo(
    () => (state ? connectionsFor(state) : []),
    [state]
  );

  // Re-measure arrows after the DOM for this step has committed.
  // A microtask bump keeps the arrow layer in sync with anchor registration.
  if (state) {
    queueMicrotask(() => setRevision((r) => (r === clampedStep ? r : clampedStep)));
  }

  if (!state) {
    return (
      <div className="panel visualization-panel">
        <h2 className="panel__title">Visualizer</h2>
        <p className="panel__hint">No trace to visualize yet.</p>
      </div>
    );
  }

  const heapObjects = Object.values(state.heap);

  return (
    <div className="panel visualization-panel">
      <div className="visualization-panel__header">
        <h2 className="panel__title">Visualizer</h2>
        <span className="panel__meta">{language.toUpperCase()}</span>
      </div>

      <div className="viz-controls">
        <button
          type="button"
          onClick={() => setStep((s) => Math.max(0, s - 1))}
          disabled={clampedStep === 0}
        >
          ‹ Prev
        </button>
        <input
          type="range"
          min={0}
          max={trace.states.length - 1}
          value={clampedStep}
          onChange={(e) => setStep(Number(e.target.value))}
        />
        <button
          type="button"
          onClick={() =>
            setStep((s) => Math.min(trace.states.length - 1, s + 1))
          }
          disabled={clampedStep === trace.states.length - 1}
        >
          Next ›
        </button>
        <span className="viz-controls__step">
          Step {clampedStep + 1} / {trace.states.length}
          {state.line !== undefined ? ` · line ${state.line}` : ""}
        </span>
      </div>

      {state.note && <p className="viz-note">{state.note}</p>}

      <div className="viz-stage" ref={containerRef}>
        <ArrowLayer
          containerRef={containerRef}
          anchors={anchorsRef.current}
          connections={connections}
          revision={revision}
        />

        <div className="viz-columns">
          <div className="viz-column">
            <h3 className="viz-column__title">Stack</h3>
            {state.stack.map((frame) => (
              <StackFrameView
                key={frame.id}
                frame={frame}
                registerCellAnchor={registerAnchor}
              />
            ))}
          </div>

          <div className="viz-column">
            <h3 className="viz-column__title">Heap</h3>
            <div className="viz-heap">
              {heapObjects.map((obj) => (
                <HeapObjectView
                  key={obj.id}
                  object={obj}
                  registerAnchor={registerAnchor}
                  registerCellAnchor={registerAnchor}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      {state.stdout && (
        <pre className="viz-stdout">{state.stdout}</pre>
      )}
    </div>
  );
}

