//! Serializable execution-trace model.
//!
//! This mirrors the frontend's `frontend/public/src/components/visualization/
//! trace.ts` so the JSON produced here deserializes directly into the
//! visualizer. The tagged `Value` / `HeapObject` enums use serde's internal
//! tagging on a `kind` field to match the TypeScript discriminated unions.

use serde::Serialize;
use std::collections::BTreeMap;

/// A value stored in a variable slot, array cell, or struct field.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind")]
pub enum Value {
    /// Inline, copied-by-value scalar (int, char, double, ...).
    #[serde(rename = "primitive")]
    Primitive {
        /// Display text, e.g. "3", "'a'", "3.14".
        display: String,
        #[serde(rename = "typeName", skip_serializing_if = "Option::is_none")]
        type_name: Option<String>,
    },
    /// A pointer into the heap. `target` is `None` for a null pointer.
    #[serde(rename = "ref")]
    Ref {
        /// Heap object id this reference points at, or null.
        target: Option<String>,
    },
}

impl Value {
    pub fn primitive(display: impl Into<String>, type_name: impl Into<String>) -> Self {
        Value::Primitive {
            display: display.into(),
            type_name: Some(type_name.into()),
        }
    }

    pub fn reference(target: Option<String>) -> Self {
        Value::Ref { target }
    }
}

/// A named binding inside a stack frame (local or parameter).
#[derive(Debug, Clone, Serialize)]
pub struct Variable {
    pub name: String,
    pub value: Value,
    #[serde(rename = "declaredType", skip_serializing_if = "Option::is_none")]
    pub declared_type: Option<String>,
}

/// One function activation on the call stack.
#[derive(Debug, Clone, Serialize)]
pub struct StackFrame {
    pub id: String,
    #[serde(rename = "functionName")]
    pub function_name: String,
    pub variables: Vec<Variable>,
    #[serde(rename = "isActive", skip_serializing_if = "Option::is_none")]
    pub is_active: Option<bool>,
}

/// Anything that can live in the heap.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind")]
pub enum HeapObject {
    #[serde(rename = "array")]
    Array {
        id: String,
        #[serde(rename = "elementType", skip_serializing_if = "Option::is_none")]
        element_type: Option<String>,
        elements: Vec<Value>,
    },
    #[serde(rename = "struct")]
    Struct {
        id: String,
        #[serde(rename = "typeName")]
        type_name: String,
        fields: Vec<Variable>,
    },
}

/// One snapshot of the program at a single execution step.
#[derive(Debug, Clone, Serialize)]
pub struct ProgramState {
    pub step: usize,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub line: Option<usize>,
    pub stack: Vec<StackFrame>,
    /// Heap objects keyed by id. BTreeMap keeps a stable, sorted order.
    pub heap: BTreeMap<String, HeapObject>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stdout: Option<String>,
}

/// The full execution trace: an ordered list of states to scrub through.
#[derive(Debug, Clone, Serialize)]
pub struct ExecutionTrace {
    pub states: Vec<ProgramState>,
}

//! A lexer for the supported subset of C.
//!
//! Produces a flat token stream with 1-based line numbers. Preprocessor
//! directives (lines starting with `#`, e.g. `#include`) are skipped, and
//! both `//` and `/* */` comments are stripped.

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    // Literals / identifiers
    Ident(String),
    Int(i64),
    Float(f64),
    Char(char),
    Str(String),

    // Keywords
    KwInt,
    KwChar,
    KwDouble,
    KwFloat,
    KwVoid,
    KwLong,
    KwIf,
    KwElse,
    KwWhile,
    KwFor,
    KwReturn,
    KwBreak,
    KwContinue,

    // Punctuation / operators
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Semicolon,
    Comma,
    Assign,     // =
    Plus,       // +
    Minus,      // -
    Star,       // *
    Slash,      // /
    Percent,    // %
    Amp,        // &
    PlusPlus,   // ++
    MinusMinus, // --
    PlusEq,     // +=
    MinusEq,    // -=
    StarEq,     // *=
    SlashEq,    // /=
    Eq,         // ==
    Ne,         // !=
    Lt,         // <
    Gt,         // >
    Le,         // <=
    Ge,         // >=
    AndAnd,     // &&
    OrOr,       // ||
    Not,        // !
    Arrow,      // ->
    Dot,        // .

    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub tok: Tok,
    pub line: usize,
}

#[derive(Debug)]
pub struct LexError {
    pub message: String,
    pub line: usize,
}

pub fn lex(src: &str) -> Result<Vec<Token>, LexError> {
    let chars: Vec<char> = src.chars().collect();
    let mut i = 0usize;
    let mut line = 1usize;
    let mut out: Vec<Token> = Vec::new();

    let n = chars.len();
    while i < n {
        let c = chars[i];

        // Newlines
        if c == '\n' {
            line += 1;
            i += 1;
            continue;
        }
        // Whitespace
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        // Preprocessor directive: skip to end of line.
        if c == '#' {
            while i < n && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        // Comments
        if c == '/' && i + 1 < n && chars[i + 1] == '/' {
            while i < n && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        if c == '/' && i + 1 < n && chars[i + 1] == '*' {
            i += 2;
            while i + 1 < n && !(chars[i] == '*' && chars[i + 1] == '/') {
                if chars[i] == '\n' {
                    line += 1;
                }
                i += 1;
            }
            i += 2; // consume */
            continue;
        }

        // Identifiers / keywords
        if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < n && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            let tok = match word.as_str() {
                "int" => Tok::KwInt,
                "char" => Tok::KwChar,
                "double" => Tok::KwDouble,
                "float" => Tok::KwFloat,
                "void" => Tok::KwVoid,
                "long" => Tok::KwLong,
                "if" => Tok::KwIf,
                "else" => Tok::KwElse,
                "while" => Tok::KwWhile,
                "for" => Tok::KwFor,
                "return" => Tok::KwReturn,
                "break" => Tok::KwBreak,
                "continue" => Tok::KwContinue,
                _ => Tok::Ident(word),
            };
            out.push(Token { tok, line });
            continue;
        }

        // Numbers (int or float)
        if c.is_ascii_digit() {
            let start = i;
            let mut is_float = false;
            while i < n && (chars[i].is_ascii_digit() || chars[i] == '.') {
                if chars[i] == '.' {
                    is_float = true;
                }
                i += 1;
            }
            // Optional float suffix f/F
            if i < n && (chars[i] == 'f' || chars[i] == 'F') {
                is_float = true;
                i += 1;
            }
            let text: String = chars[start..i].iter().filter(|c| **c != 'f' && **c != 'F').collect();
            if is_float {
                let v: f64 = text.parse().map_err(|_| LexError {
                    message: format!("invalid float literal '{}'", text),
                    line,
                })?;
                out.push(Token { tok: Tok::Float(v), line });
            } else {
                let v: i64 = text.parse().map_err(|_| LexError {
                    message: format!("invalid integer literal '{}'", text),
                    line,
                })?;
                out.push(Token { tok: Tok::Int(v), line });
            }
            continue;
        }

        // Char literal
        if c == '\'' {
            i += 1;
            if i >= n {
                return Err(LexError { message: "unterminated char literal".into(), line });
            }
            let ch = if chars[i] == '\\' {
                i += 1;
                if i >= n {
                    return Err(LexError { message: "unterminated escape".into(), line });
                }
                let e = decode_escape(chars[i]);
                i += 1;
                e
            } else {
                let ch = chars[i];
                i += 1;
                ch
            };
            if i >= n || chars[i] != '\'' {
                return Err(LexError { message: "unterminated char literal".into(), line });
            }
            i += 1; // closing '
            out.push(Token { tok: Tok::Char(ch), line });
            continue;
        }

        // String literal
        if c == '"' {
            i += 1;
            let mut s = String::new();
            while i < n && chars[i] != '"' {
                if chars[i] == '\\' {
                    i += 1;
                    if i >= n {
                        return Err(LexError { message: "unterminated escape".into(), line });
                    }
                    s.push(decode_escape(chars[i]));
                    i += 1;
                } else {
                    if chars[i] == '\n' {
                        line += 1;
                    }
                    s.push(chars[i]);
                    i += 1;
                }
            }
            if i >= n {
                return Err(LexError { message: "unterminated string literal".into(), line });
            }
            i += 1; // closing "
            out.push(Token { tok: Tok::Str(s), line });
            continue;
        }

        // Operators / punctuation (two-char first)
        let two: Option<Tok> = if i + 1 < n {
            match (c, chars[i + 1]) {
                ('+', '+') => Some(Tok::PlusPlus),
                ('-', '-') => Some(Tok::MinusMinus),
                ('+', '=') => Some(Tok::PlusEq),
                ('-', '=') => Some(Tok::MinusEq),
                ('*', '=') => Some(Tok::StarEq),
                ('/', '=') => Some(Tok::SlashEq),
                ('=', '=') => Some(Tok::Eq),
                ('!', '=') => Some(Tok::Ne),
                ('<', '=') => Some(Tok::Le),
                ('>', '=') => Some(Tok::Ge),
                ('&', '&') => Some(Tok::AndAnd),
                ('|', '|') => Some(Tok::OrOr),
                ('-', '>') => Some(Tok::Arrow),
                _ => None,
            }
        } else {
            None
        };
        if let Some(tok) = two {
            out.push(Token { tok, line });
            i += 2;
            continue;
        }

        let one = match c {
            '(' => Tok::LParen,
            ')' => Tok::RParen,
            '{' => Tok::LBrace,
            '}' => Tok::RBrace,
            '[' => Tok::LBracket,
            ']' => Tok::RBracket,
            ';' => Tok::Semicolon,
            ',' => Tok::Comma,
            '=' => Tok::Assign,
            '+' => Tok::Plus,
            '-' => Tok::Minus,
            '*' => Tok::Star,
            '/' => Tok::Slash,
            '%' => Tok::Percent,
            '&' => Tok::Amp,
            '<' => Tok::Lt,
            '>' => Tok::Gt,
            '!' => Tok::Not,
            '.' => Tok::Dot,
            other => {
                return Err(LexError {
                    message: format!("unexpected character '{}'", other),
                    line,
                })
            }
        };
        out.push(Token { tok: one, line });
        i += 1;
    }

    out.push(Token { tok: Tok::Eof, line });
    Ok(out)
}

fn decode_escape(c: char) -> char {
    match c {
        'n' => '\n',
        't' => '\t',
        'r' => '\r',
        '0' => '\0',
        '\\' => '\\',
        '\'' => '\'',
        '"' => '"',
        other => other,
    }
}

//! AST for the supported subset of C.

/// A declared/base type. Pointers are tracked by `pointer_depth`.
#[derive(Debug, Clone, PartialEq)]
pub enum BaseType {
    Int,
    Char,
    Double,
    Float,
    Long,
    Void,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CType {
    pub base: BaseType,
    /// Number of `*` levels (0 = plain value, 1 = `int*`, etc.).
    pub pointer_depth: u32,
}

impl CType {
    pub fn display(&self) -> String {
        let base = match self.base {
            BaseType::Int => "int",
            BaseType::Char => "char",
            BaseType::Double => "double",
            BaseType::Float => "float",
            BaseType::Long => "long",
            BaseType::Void => "void",
        };
        format!("{}{}", base, "*".repeat(self.pointer_depth as usize))
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Gt,
    Le,
    Ge,
    And,
    Or,
}

#[derive(Debug, Clone, PartialEq)]
pub enum UnOp {
    Neg,
    Not,
    /// Address-of: &x
    AddrOf,
    /// Dereference: *p
    Deref,
}

#[derive(Debug, Clone)]
pub enum Expr {
    IntLit(i64),
    FloatLit(f64),
    CharLit(char),
    StrLit(String),
    Ident(String),
    /// Array indexing: base[index]
    Index(Box<Expr>, Box<Expr>),
    /// Unary operation.
    Unary(UnOp, Box<Expr>),
    /// Binary operation.
    Binary(BinOp, Box<Expr>, Box<Expr>),
    /// Assignment: target = value. Target is an lvalue expression.
    Assign(Box<Expr>, Box<Expr>),
    /// Function call: name(args...).
    Call(String, Vec<Expr>),
    /// Pre/post increment/decrement; bool = is_prefix, i64 = +1/-1.
    IncDec { target: Box<Expr>, delta: i64, prefix: bool },
}

#[derive(Debug, Clone)]
pub enum Stmt {
    /// Variable declaration, optionally with an initializer.
    /// For arrays, `array_len` is Some(n).
    VarDecl {
        ty: CType,
        name: String,
        array_len: Option<usize>,
        init: Option<Expr>,
        /// For `int a[] = {1,2,3}` or `int a[3] = {...}`.
        array_init: Option<Vec<Expr>>,
        line: usize,
    },
    ExprStmt(Expr, usize),
    If {
        cond: Expr,
        then_branch: Vec<Stmt>,
        else_branch: Option<Vec<Stmt>>,
        line: usize,
    },
    While {
        cond: Expr,
        body: Vec<Stmt>,
        line: usize,
    },
    For {
        init: Option<Box<Stmt>>,
        cond: Option<Expr>,
        step: Option<Expr>,
        body: Vec<Stmt>,
        line: usize,
    },
    Return(Option<Expr>, usize),
    Break(usize),
    Continue(usize),
    Block(Vec<Stmt>),
}

#[derive(Debug, Clone)]
pub struct Param {
    pub ty: CType,
    pub name: String,
}

#[derive(Debug, Clone)]
pub struct Function {
    pub ret: CType,
    pub name: String,
    pub params: Vec<Param>,
    pub body: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub struct Program {
    pub functions: Vec<Function>,
}

//! Recursive-descent parser for the supported subset of C.

use super::ast::*;
use super::lexer::{Tok, Token};

#[derive(Debug)]
pub struct ParseError {
    pub message: String,
    pub line: usize,
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
}

type PResult<T> = Result<T, ParseError>;

impl Parser {
    pub fn new(toks: Vec<Token>) -> Self {
        Parser { toks, pos: 0 }
    }

    pub fn parse_program(&mut self) -> PResult<Program> {
        let mut functions = Vec::new();
        while !self.check(&Tok::Eof) {
            functions.push(self.parse_function()?);
        }
        Ok(Program { functions })
    }

    // ---- token helpers ----------------------------------------------------

    fn peek(&self) -> &Tok {
        &self.toks[self.pos].tok
    }

    fn peek_at(&self, offset: usize) -> &Tok {
        let idx = (self.pos + offset).min(self.toks.len() - 1);
        &self.toks[idx].tok
    }

    fn line(&self) -> usize {
        self.toks[self.pos].line
    }

    fn check(&self, t: &Tok) -> bool {
        self.peek() == t
    }

    fn advance(&mut self) -> Tok {
        let t = self.toks[self.pos].tok.clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn eat(&mut self, t: &Tok) -> PResult<()> {
        if self.check(t) {
            self.advance();
            Ok(())
        } else {
            Err(ParseError {
                message: format!("expected {:?}, found {:?}", t, self.peek()),
                line: self.line(),
            })
        }
    }

    fn match_tok(&mut self, t: &Tok) -> bool {
        if self.check(t) {
            self.advance();
            true
        } else {
            false
        }
    }

    // ---- types ------------------------------------------------------------

    fn is_type_start(&self) -> bool {
        matches!(
            self.peek(),
            Tok::KwInt
                | Tok::KwChar
                | Tok::KwDouble
                | Tok::KwFloat
                | Tok::KwVoid
                | Tok::KwLong
        )
    }

    fn parse_type(&mut self) -> PResult<CType> {
        let base = match self.advance() {
            Tok::KwInt => BaseType::Int,
            Tok::KwChar => BaseType::Char,
            Tok::KwDouble => BaseType::Double,
            Tok::KwFloat => BaseType::Float,
            Tok::KwLong => BaseType::Long,
            Tok::KwVoid => BaseType::Void,
            other => {
                return Err(ParseError {
                    message: format!("expected a type, found {:?}", other),
                    line: self.line(),
                })
            }
        };
        let mut pointer_depth = 0;
        while self.match_tok(&Tok::Star) {
            pointer_depth += 1;
        }
        Ok(CType { base, pointer_depth })
    }

    fn expect_ident(&mut self) -> PResult<String> {
        match self.advance() {
            Tok::Ident(name) => Ok(name),
            other => Err(ParseError {
                message: format!("expected identifier, found {:?}", other),
                line: self.line(),
            }),
        }
    }

    // ---- functions --------------------------------------------------------

    fn parse_function(&mut self) -> PResult<Function> {
        let ret = self.parse_type()?;
        let name = self.expect_ident()?;
        self.eat(&Tok::LParen)?;
        let mut params = Vec::new();
        if !self.check(&Tok::RParen) {
            // Handle `void` param list.
            if self.check(&Tok::KwVoid) && self.peek_at(1) == &Tok::RParen {
                self.advance();
            } else {
                loop {
                    let ty = self.parse_type()?;
                    let pname = self.expect_ident()?;
                    params.push(Param { ty, name: pname });
                    if !self.match_tok(&Tok::Comma) {
                        break;
                    }
                }
            }
        }
        self.eat(&Tok::RParen)?;
        self.eat(&Tok::LBrace)?;
        let body = self.parse_block_body()?;
        Ok(Function { ret, name, params, body })
    }

    /// Parse statements until a closing brace (which is consumed).
    fn parse_block_body(&mut self) -> PResult<Vec<Stmt>> {
        let mut stmts = Vec::new();
        while !self.check(&Tok::RBrace) && !self.check(&Tok::Eof) {
            stmts.push(self.parse_stmt()?);
        }
        self.eat(&Tok::RBrace)?;
        Ok(stmts)
    }

    // ---- statements -------------------------------------------------------

    fn parse_stmt(&mut self) -> PResult<Stmt> {
        let line = self.line();
        match self.peek() {
            Tok::LBrace => {
                self.advance();
                Ok(Stmt::Block(self.parse_block_body()?))
            }
            Tok::KwIf => self.parse_if(),
            Tok::KwWhile => self.parse_while(),
            Tok::KwFor => self.parse_for(),
            Tok::KwReturn => {
                self.advance();
                let expr = if self.check(&Tok::Semicolon) {
                    None
                } else {
                    Some(self.parse_expr()?)
                };
                self.eat(&Tok::Semicolon)?;
                Ok(Stmt::Return(expr, line))
            }
            Tok::KwBreak => {
                self.advance();
                self.eat(&Tok::Semicolon)?;
                Ok(Stmt::Break(line))
            }
            Tok::KwContinue => {
                self.advance();
                self.eat(&Tok::Semicolon)?;
                Ok(Stmt::Continue(line))
            }
            _ if self.is_type_start() => self.parse_var_decl(),
            _ => {
                let expr = self.parse_expr()?;
                self.eat(&Tok::Semicolon)?;
                Ok(Stmt::ExprStmt(expr, line))
            }
        }
    }

    fn parse_var_decl(&mut self) -> PResult<Stmt> {
        let line = self.line();
        let ty = self.parse_type()?;
        let name = self.expect_ident()?;

        // Array declaration: name[len]
        let mut array_len = None;
        if self.match_tok(&Tok::LBracket) {
            if let Tok::Int(n) = self.peek().clone() {
                self.advance();
                array_len = Some(n as usize);
            } else {
                array_len = Some(0); // size inferred from initializer
            }
            self.eat(&Tok::RBracket)?;
        }

        let mut init = None;
        let mut array_init = None;
        if self.match_tok(&Tok::Assign) {
            if self.check(&Tok::LBrace) {
                // Array initializer list { a, b, c }
                self.advance();
                let mut elems = Vec::new();
                if !self.check(&Tok::RBrace) {
                    loop {
                        elems.push(self.parse_expr()?);
                        if !self.match_tok(&Tok::Comma) {
                            break;
                        }
                        if self.check(&Tok::RBrace) {
                            break;
                        }
                    }
                }
                self.eat(&Tok::RBrace)?;
                if array_len.is_none() {
                    array_len = Some(elems.len());
                }
                array_init = Some(elems);
            } else {
                init = Some(self.parse_expr()?);
            }
        }
        self.eat(&Tok::Semicolon)?;
        Ok(Stmt::VarDecl {
            ty,
            name,
            array_len,
            init,
            array_init,
            line,
        })
    }

    fn parse_if(&mut self) -> PResult<Stmt> {
        let line = self.line();
        self.eat(&Tok::KwIf)?;
        self.eat(&Tok::LParen)?;
        let cond = self.parse_expr()?;
        self.eat(&Tok::RParen)?;
        let then_branch = self.parse_stmt_as_block()?;
        let else_branch = if self.match_tok(&Tok::KwElse) {
            Some(self.parse_stmt_as_block()?)
        } else {
            None
        };
        Ok(Stmt::If { cond, then_branch, else_branch, line })
    }

    fn parse_while(&mut self) -> PResult<Stmt> {
        let line = self.line();
        self.eat(&Tok::KwWhile)?;
        self.eat(&Tok::LParen)?;
        let cond = self.parse_expr()?;
        self.eat(&Tok::RParen)?;
        let body = self.parse_stmt_as_block()?;
        Ok(Stmt::While { cond, body, line })
    }

    fn parse_for(&mut self) -> PResult<Stmt> {
        let line = self.line();
        self.eat(&Tok::KwFor)?;
        self.eat(&Tok::LParen)?;

        let init = if self.check(&Tok::Semicolon) {
            self.advance();
            None
        } else if self.is_type_start() {
            Some(Box::new(self.parse_var_decl()?))
        } else {
            let e = self.parse_expr()?;
            self.eat(&Tok::Semicolon)?;
            Some(Box::new(Stmt::ExprStmt(e, line)))
        };

        let cond = if self.check(&Tok::Semicolon) {
            None
        } else {
            Some(self.parse_expr()?)
        };
        self.eat(&Tok::Semicolon)?;

        let step = if self.check(&Tok::RParen) {
            None
        } else {
            Some(self.parse_expr()?)
        };
        self.eat(&Tok::RParen)?;

        let body = self.parse_stmt_as_block()?;
        Ok(Stmt::For { init, cond, step, body, line })
    }

    /// Parse a single statement, wrapping a non-block as a one-element block.
    fn parse_stmt_as_block(&mut self) -> PResult<Vec<Stmt>> {
        if self.check(&Tok::LBrace) {
            self.advance();
            self.parse_block_body()
        } else {
            Ok(vec![self.parse_stmt()?])
        }
    }

    // ---- expressions (precedence climbing) --------------------------------

    fn parse_expr(&mut self) -> PResult<Expr> {
        self.parse_assignment()
    }

    fn parse_assignment(&mut self) -> PResult<Expr> {
        let left = self.parse_logic_or()?;
        match self.peek() {
            Tok::Assign => {
                self.advance();
                let right = self.parse_assignment()?;
                Ok(Expr::Assign(Box::new(left), Box::new(right)))
            }
            Tok::PlusEq | Tok::MinusEq | Tok::StarEq | Tok::SlashEq => {
                let op = match self.advance() {
                    Tok::PlusEq => BinOp::Add,
                    Tok::MinusEq => BinOp::Sub,
                    Tok::StarEq => BinOp::Mul,
                    Tok::SlashEq => BinOp::Div,
                    _ => unreachable!(),
                };
                let right = self.parse_assignment()?;
                // a += b  =>  a = a + b
                let combined = Expr::Binary(op, Box::new(left.clone()), Box::new(right));
                Ok(Expr::Assign(Box::new(left), Box::new(combined)))
            }
            _ => Ok(left),
        }
    }

    fn parse_logic_or(&mut self) -> PResult<Expr> {
        let mut left = self.parse_logic_and()?;
        while self.check(&Tok::OrOr) {
            self.advance();
            let right = self.parse_logic_and()?;
            left = Expr::Binary(BinOp::Or, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_logic_and(&mut self) -> PResult<Expr> {
        let mut left = self.parse_equality()?;
        while self.check(&Tok::AndAnd) {
            self.advance();
            let right = self.parse_equality()?;
            left = Expr::Binary(BinOp::And, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_equality(&mut self) -> PResult<Expr> {
        let mut left = self.parse_relational()?;
        loop {
            let op = match self.peek() {
                Tok::Eq => BinOp::Eq,
                Tok::Ne => BinOp::Ne,
                _ => break,
            };
            self.advance();
            let right = self.parse_relational()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_relational(&mut self) -> PResult<Expr> {
        let mut left = self.parse_additive()?;
        loop {
            let op = match self.peek() {
                Tok::Lt => BinOp::Lt,
                Tok::Gt => BinOp::Gt,
                Tok::Le => BinOp::Le,
                Tok::Ge => BinOp::Ge,
                _ => break,
            };
            self.advance();
            let right = self.parse_additive()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_additive(&mut self) -> PResult<Expr> {
        let mut left = self.parse_multiplicative()?;
        loop {
            let op = match self.peek() {
                Tok::Plus => BinOp::Add,
                Tok::Minus => BinOp::Sub,
                _ => break,
            };
            self.advance();
            let right = self.parse_multiplicative()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> PResult<Expr> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek() {
                Tok::Star => BinOp::Mul,
                Tok::Slash => BinOp::Div,
                Tok::Percent => BinOp::Mod,
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> PResult<Expr> {
        match self.peek() {
            Tok::Minus => {
                self.advance();
                Ok(Expr::Unary(UnOp::Neg, Box::new(self.parse_unary()?)))
            }
            Tok::Not => {
                self.advance();
                Ok(Expr::Unary(UnOp::Not, Box::new(self.parse_unary()?)))
            }
            Tok::Amp => {
                self.advance();
                Ok(Expr::Unary(UnOp::AddrOf, Box::new(self.parse_unary()?)))
            }
            Tok::Star => {
                self.advance();
                Ok(Expr::Unary(UnOp::Deref, Box::new(self.parse_unary()?)))
            }
            Tok::PlusPlus => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::IncDec { target: Box::new(e), delta: 1, prefix: true })
            }
            Tok::MinusMinus => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::IncDec { target: Box::new(e), delta: -1, prefix: true })
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> PResult<Expr> {
        let mut expr = self.parse_primary()?;
        loop {
            match self.peek() {
                Tok::LBracket => {
                    self.advance();
                    let idx = self.parse_expr()?;
                    self.eat(&Tok::RBracket)?;
                    expr = Expr::Index(Box::new(expr), Box::new(idx));
                }
                Tok::PlusPlus => {
                    self.advance();
                    expr = Expr::IncDec { target: Box::new(expr), delta: 1, prefix: false };
                }
                Tok::MinusMinus => {
                    self.advance();
                    expr = Expr::IncDec { target: Box::new(expr), delta: -1, prefix: false };
                }
                _ => break,
            }
        }
        Ok(expr)
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        match self.peek().clone() {
            Tok::Int(n) => {
                self.advance();
                Ok(Expr::IntLit(n))
            }
            Tok::Float(f) => {
                self.advance();
                Ok(Expr::FloatLit(f))
            }
            Tok::Char(c) => {
                self.advance();
                Ok(Expr::CharLit(c))
            }
            Tok::Str(s) => {
                self.advance();
                Ok(Expr::StrLit(s))
            }
            Tok::LParen => {
                self.advance();
                let e = self.parse_expr()?;
                self.eat(&Tok::RParen)?;
                Ok(e)
            }
            Tok::Ident(name) => {
                self.advance();
                if self.check(&Tok::LParen) {
                    self.advance();
                    let mut args = Vec::new();
                    if !self.check(&Tok::RParen) {
                        loop {
                            args.push(self.parse_expr()?);
                            if !self.match_tok(&Tok::Comma) {
                                break;
                            }
                        }
                    }
                    self.eat(&Tok::RParen)?;
                    Ok(Expr::Call(name, args))
                } else {
                    Ok(Expr::Ident(name))
                }
            }
            other => Err(ParseError {
                message: format!("unexpected token in expression: {:?}", other),
                line: self.line(),
            }),
        }
    }
}

//! Tree-walking interpreter for the supported subset of C.
//!
//! It evaluates the AST while recording a `ProgramState` snapshot after each
//! statement, assembling an `ExecutionTrace` for the visualizer. The runtime
//! value model distinguishes:
//!   - scalars (int/char/double) -> rendered as primitive boxes (value sem.)
//!   - pointers (address of a storage cell or heap object) -> rendered as
//!     reference arrows (reference semantics)
//!   - heap arrays / heap blocks from malloc -> heap objects

use std::collections::{BTreeMap, HashMap};

use super::ast::*;
use crate::trace::{
    ExecutionTrace, HeapObject, ProgramState, StackFrame, Value as TValue, Variable as TVariable,
};

const MAX_STEPS: usize = 2000;

#[derive(Debug)]
pub struct RuntimeError {
    pub message: String,
    pub line: usize,
}

/// A runtime scalar.
#[derive(Debug, Clone)]
enum Scalar {
    Int(i64),
    Double(f64),
    Char(char),
}

impl Scalar {
    fn as_i64(&self) -> i64 {
        match self {
            Scalar::Int(i) => *i,
            Scalar::Char(c) => *c as i64,
            Scalar::Double(d) => *d as i64,
        }
    }

    fn as_f64(&self) -> f64 {
        match self {
            Scalar::Int(i) => *i as f64,
            Scalar::Char(c) => *c as i64 as f64,
            Scalar::Double(d) => *d,
        }
    }

    fn truthy(&self) -> bool {
        match self {
            Scalar::Int(i) => *i != 0,
            Scalar::Char(c) => *c != '\0',
            Scalar::Double(d) => *d != 0.0,
        }
    }

    fn display(&self) -> String {
        match self {
            Scalar::Int(i) => i.to_string(),
            Scalar::Char(c) => format!("'{}'", c.escape_default()),
            Scalar::Double(d) => format!("{}", d),
        }
    }

    fn type_name(&self) -> &'static str {
        match self {
            Scalar::Int(_) => "int",
            Scalar::Char(_) => "char",
            Scalar::Double(_) => "double",
        }
    }
}

/// A runtime value: a scalar, a pointer, or a heap-array pointer (decayed).
#[derive(Debug, Clone)]
enum RValue {
    Scalar(Scalar),
    /// Pointer to a storage location (see `Location`). None = null pointer.
    Pointer(Option<Location>),
    /// Void / no value (e.g. result of a void call).
    Void,
}

/// Where a value is stored (the target of a pointer / an lvalue address).
#[derive(Debug, Clone)]
enum Location {
    /// A named variable slot in a stack frame (frame index + variable name).
    Local { frame: usize, name: String },
    /// A heap array cell: object id + index.
    HeapCell { id: String, index: usize },
}

/// Runtime storage for one variable slot.
#[derive(Debug, Clone)]
enum Slot {
    Scalar(Scalar),
    Pointer(Option<Location>),
    /// A local array lives in the heap; the slot holds the heap id + type.
    ArrayRef { id: String, element_type: BaseType },
}

struct Frame {
    function_name: String,
    /// Insertion-ordered variable names for stable display.
    order: Vec<String>,
    slots: HashMap<String, Slot>,
    declared: HashMap<String, CType>,
}

/// A heap array of scalars (we keep raw scalars + element type).
struct HeapArray {
    element_type: BaseType,
    cells: Vec<Scalar>,
}

enum Flow {
    Normal,
    Break,
    Continue,
    Return(RValue),
}

pub struct Interp<'a> {
    program: &'a Program,
    functions: HashMap<String, &'a Function>,
    frames: Vec<Frame>,
    heap: HashMap<String, HeapArray>,
    next_heap_id: usize,
    states: Vec<ProgramState>,
    stdout: String,
    step_counter: usize,
}

impl<'a> Interp<'a> {
    pub fn new(program: &'a Program) -> Self {
        let mut functions = HashMap::new();
        for f in &program.functions {
            functions.insert(f.name.clone(), f);
        }
        Interp {
            program,
            functions,
            frames: Vec::new(),
            heap: HashMap::new(),
            next_heap_id: 0,
            states: Vec::new(),
            stdout: String::new(),
            step_counter: 0,
        }
    }

    pub fn run(mut self) -> Result<ExecutionTrace, RuntimeError> {
        let main = self.functions.get("main").copied().ok_or(RuntimeError {
            message: "no 'main' function found".into(),
            line: 0,
        })?;
        self.call_function(main, Vec::new(), 0)?;
        Ok(ExecutionTrace { states: self.states })
    }

    // ---- heap helpers -----------------------------------------------------

    fn fresh_heap_id(&mut self, prefix: &str) -> String {
        let id = format!("{}_{}", prefix, self.next_heap_id);
        self.next_heap_id += 1;
        id
    }

    // ---- function call ----------------------------------------------------

    fn call_function(
        &mut self,
        func: &'a Function,
        args: Vec<RValue>,
        line: usize,
    ) -> Result<RValue, RuntimeError> {
        if self.frames.len() > 100 {
            return Err(RuntimeError {
                message: "call stack overflow (recursion too deep)".into(),
                line,
            });
        }

        let mut frame = Frame {
            function_name: func.name.clone(),
            order: Vec::new(),
            slots: HashMap::new(),
            declared: HashMap::new(),
        };

        for (param, arg) in func.params.iter().zip(args.into_iter()) {
            let slot = match arg {
                RValue::Scalar(s) => Slot::Scalar(coerce_scalar(s, &param.ty.base)),
                RValue::Pointer(p) => Slot::Pointer(p),
                RValue::Void => Slot::Scalar(Scalar::Int(0)),
            };
            frame.order.push(param.name.clone());
            frame.slots.insert(param.name.clone(), slot);
            frame.declared.insert(param.name.clone(), param.ty.clone());
        }

        self.frames.push(frame);

        let flow = self.exec_block(&func.body)?;
        let ret = match flow {
            Flow::Return(v) => v,
            _ => RValue::Void,
        };

        self.frames.pop();
        Ok(ret)
    }

    // ---- statements -------------------------------------------------------

    fn exec_block(&mut self, stmts: &[Stmt]) -> Result<Flow, RuntimeError> {
        for stmt in stmts {
            let flow = self.exec_stmt(stmt)?;
            if !matches!(flow, Flow::Normal) {
                return Ok(flow);
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_stmt(&mut self, stmt: &Stmt) -> Result<Flow, RuntimeError> {
        self.step_counter += 1;
        if self.step_counter > MAX_STEPS {
            return Err(RuntimeError {
                message: "execution step limit exceeded (possible infinite loop)".into(),
                line: stmt_line(stmt),
            });
        }

        match stmt {
            Stmt::VarDecl {
                ty,
                name,
                array_len,
                init,
                array_init,
                line,
            } => {
                self.exec_var_decl(ty, name, *array_len, init, array_init, *line)?;
                self.snapshot(Some(*line), Some(format!("Declared {}", name)));
                Ok(Flow::Normal)
            }
            Stmt::ExprStmt(expr, line) => {
                self.eval_expr(expr)?;
                self.snapshot(Some(*line), None);
                Ok(Flow::Normal)
            }
            Stmt::If {
                cond,
                then_branch,
                else_branch,
                line,
            } => {
                let c = self.eval_scalar(cond)?;
                self.snapshot(Some(*line), Some(format!("if (...) -> {}", c.truthy())));
                if c.truthy() {
                    self.exec_block(then_branch)
                } else if let Some(eb) = else_branch {
                    self.exec_block(eb)
                } else {
                    Ok(Flow::Normal)
                }
            }
            Stmt::While { cond, body, line } => {
                let mut iter = 0;
                loop {
                    let c = self.eval_scalar(cond)?;
                    self.snapshot(
                        Some(*line),
                        Some(format!("while (...) iteration {}, cond = {}", iter, c.truthy())),
                    );
                    if !c.truthy() {
                        break;
                    }
                    match self.exec_block(body)? {
                        Flow::Break => break,
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                        _ => {}
                    }
                    iter += 1;
                }
                Ok(Flow::Normal)
            }
            Stmt::For {
                init,
                cond,
                step,
                body,
                line,
            } => {
                if let Some(init_stmt) = init {
                    self.exec_stmt(init_stmt)?;
                }
                let mut iter = 0;
                loop {
                    let keep = match cond {
                        Some(c) => self.eval_scalar(c)?.truthy(),
                        None => true,
                    };
                    self.snapshot(
                        Some(*line),
                        Some(format!("for loop iteration {}, cond = {}", iter, keep)),
                    );
                    if !keep {
                        break;
                    }
                    match self.exec_block(body)? {
                        Flow::Break => break,
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                        _ => {}
                    }
                    if let Some(s) = step {
                        self.eval_expr(s)?;
                    }
                    iter += 1;
                }
                Ok(Flow::Normal)
            }
            Stmt::Return(expr, line) => {
                let v = match expr {
                    Some(e) => self.eval_expr(e)?,
                    None => RValue::Void,
                };
                self.snapshot(Some(*line), Some("return".into()));
                Ok(Flow::Return(v))
            }
            Stmt::Break(_) => Ok(Flow::Break),
            Stmt::Continue(_) => Ok(Flow::Continue),
            Stmt::Block(stmts) => self.exec_block(stmts),
        }
    }

    fn exec_var_decl(
        &mut self,
        ty: &CType,
        name: &str,
        array_len: Option<usize>,
        init: &Option<Expr>,
        array_init: &Option<Vec<Expr>>,
        _line: usize,
    ) -> Result<(), RuntimeError> {
        if let Some(len) = array_len {
            // Local array -> allocate a heap array.
            let id = self.fresh_heap_id("arr");
            let mut cells: Vec<Scalar> = Vec::new();
            if let Some(elems) = array_init {
                for e in elems {
                    let s = self.eval_scalar(e)?;
                    cells.push(coerce_scalar(s, &ty.base));
                }
            }
            while cells.len() < len {
                cells.push(default_scalar(&ty.base));
            }
            self.heap.insert(
                id.clone(),
                HeapArray {
                    element_type: ty.base.clone(),
                    cells,
                },
            );
            let frame = self.frames.last_mut().unwrap();
            frame.order.push(name.to_string());
            frame
                .slots
                .insert(name.to_string(), Slot::ArrayRef { id, element_type: ty.base.clone() });
            frame.declared.insert(name.to_string(), ty.clone());
            return Ok(());
        }

        // Scalar or pointer.
        let slot = if ty.pointer_depth > 0 {
            match init {
                Some(e) => {
                    let v = self.eval_expr(e)?;
                    match v {
                        RValue::Pointer(p) => Slot::Pointer(p),
                        RValue::Scalar(s) if s.as_i64() == 0 => Slot::Pointer(None),
                        _ => Slot::Pointer(None),
                    }
                }
                None => Slot::Pointer(None),
            }
        } else {
            let s = match init {
                Some(e) => self.eval_scalar(e)?,
                None => default_scalar(&ty.base),
            };
            Slot::Scalar(coerce_scalar(s, &ty.base))
        };

        let frame = self.frames.last_mut().unwrap();
        frame.order.push(name.to_string());
        frame.slots.insert(name.to_string(), slot);
        frame.declared.insert(name.to_string(), ty.clone());
        Ok(())
    }

    // ---- expression evaluation -------------------------------------------

    fn eval_scalar(&mut self, expr: &Expr) -> Result<Scalar, RuntimeError> {
        match self.eval_expr(expr)? {
            RValue::Scalar(s) => Ok(s),
            RValue::Pointer(_) => Ok(Scalar::Int(0)),
            RValue::Void => Ok(Scalar::Int(0)),
        }
    }

    fn eval_expr(&mut self, expr: &Expr) -> Result<RValue, RuntimeError> {
        match expr {
            Expr::IntLit(n) => Ok(RValue::Scalar(Scalar::Int(*n))),
            Expr::FloatLit(f) => Ok(RValue::Scalar(Scalar::Double(*f))),
            Expr::CharLit(c) => Ok(RValue::Scalar(Scalar::Char(*c))),
            Expr::StrLit(_) => Ok(RValue::Scalar(Scalar::Int(0))), // strings only used in printf
            Expr::Ident(name) => self.read_ident(name),
            Expr::Index(base, idx) => {
                let loc = self.lvalue_of_index(base, idx)?;
                self.read_location(&loc)
            }
            Expr::Unary(op, inner) => self.eval_unary(op, inner),
            Expr::Binary(op, l, r) => self.eval_binary(op, l, r),
            Expr::Assign(target, value) => {
                let v = self.eval_expr(value)?;
                let loc = self.lvalue_of(target)?;
                self.write_location(&loc, v.clone())?;
                Ok(v)
            }
            Expr::IncDec { target, delta, prefix } => {
                let loc = self.lvalue_of(target)?;
                let old = self.read_location(&loc)?;
                let old_s = match old {
                    RValue::Scalar(s) => s,
                    _ => Scalar::Int(0),
                };
                let new_s = Scalar::Int(old_s.as_i64() + delta);
                self.write_location(&loc, RValue::Scalar(new_s.clone()))?;
                Ok(RValue::Scalar(if *prefix { new_s } else { old_s }))
            }
            Expr::Call(name, args) => self.eval_call(name, args),
        }
    }

    fn eval_unary(&mut self, op: &UnOp, inner: &Expr) -> Result<RValue, RuntimeError> {
        match op {
            UnOp::Neg => {
                let s = self.eval_scalar(inner)?;
                Ok(RValue::Scalar(match s {
                    Scalar::Double(d) => Scalar::Double(-d),
                    other => Scalar::Int(-other.as_i64()),
                }))
            }
            UnOp::Not => {
                let s = self.eval_scalar(inner)?;
                Ok(RValue::Scalar(Scalar::Int(if s.truthy() { 0 } else { 1 })))
            }
            UnOp::AddrOf => {
                let loc = self.lvalue_of(inner)?;
                Ok(RValue::Pointer(Some(loc)))
            }
            UnOp::Deref => {
                let v = self.eval_expr(inner)?;
                match v {
                    RValue::Pointer(Some(loc)) => self.read_location(&loc),
                    RValue::Pointer(None) => Err(RuntimeError {
                        message: "dereferenced a null pointer".into(),
                        line: 0,
                    }),
                    _ => Err(RuntimeError {
                        message: "cannot dereference a non-pointer".into(),
                        line: 0,
                    }),
                }
            }
        }
    }

    fn eval_binary(&mut self, op: &BinOp, l: &Expr, r: &Expr) -> Result<RValue, RuntimeError> {
        // Short-circuit logicals.
        if let BinOp::And = op {
            let lv = self.eval_scalar(l)?;
            if !lv.truthy() {
                return Ok(RValue::Scalar(Scalar::Int(0)));
            }
            let rv = self.eval_scalar(r)?;
            return Ok(RValue::Scalar(Scalar::Int(if rv.truthy() { 1 } else { 0 })));
        }
        if let BinOp::Or = op {
            let lv = self.eval_scalar(l)?;
            if lv.truthy() {
                return Ok(RValue::Scalar(Scalar::Int(1)));
            }
            let rv = self.eval_scalar(r)?;
            return Ok(RValue::Scalar(Scalar::Int(if rv.truthy() { 1 } else { 0 })));
        }

        let lv = self.eval_scalar(l)?;
        let rv = self.eval_scalar(r)?;
        let use_float = matches!(lv, Scalar::Double(_)) || matches!(rv, Scalar::Double(_));

        let result = match op {
            BinOp::Add if use_float => Scalar::Double(lv.as_f64() + rv.as_f64()),
            BinOp::Sub if use_float => Scalar::Double(lv.as_f64() - rv.as_f64()),
            BinOp::Mul if use_float => Scalar::Double(lv.as_f64() * rv.as_f64()),
            BinOp::Div if use_float => Scalar::Double(lv.as_f64() / rv.as_f64()),
            BinOp::Add => Scalar::Int(lv.as_i64() + rv.as_i64()),
            BinOp::Sub => Scalar::Int(lv.as_i64() - rv.as_i64()),
            BinOp::Mul => Scalar::Int(lv.as_i64() * rv.as_i64()),
            BinOp::Div => {
                if rv.as_i64() == 0 {
                    return Err(RuntimeError { message: "division by zero".into(), line: 0 });
                }
                Scalar::Int(lv.as_i64() / rv.as_i64())
            }
            BinOp::Mod => {
                if rv.as_i64() == 0 {
                    return Err(RuntimeError { message: "modulo by zero".into(), line: 0 });
                }
                Scalar::Int(lv.as_i64() % rv.as_i64())
            }
            BinOp::Eq => Scalar::Int(bool_i(if use_float {
                lv.as_f64() == rv.as_f64()
            } else {
                lv.as_i64() == rv.as_i64()
            })),
            BinOp::Ne => Scalar::Int(bool_i(if use_float {
                lv.as_f64() != rv.as_f64()
            } else {
                lv.as_i64() != rv.as_i64()
            })),
            BinOp::Lt => Scalar::Int(bool_i(lv.as_f64() < rv.as_f64())),
            BinOp::Gt => Scalar::Int(bool_i(lv.as_f64() > rv.as_f64())),
            BinOp::Le => Scalar::Int(bool_i(lv.as_f64() <= rv.as_f64())),
            BinOp::Ge => Scalar::Int(bool_i(lv.as_f64() >= rv.as_f64())),
            BinOp::And | BinOp::Or => unreachable!(),
        };
        Ok(RValue::Scalar(result))
    }

    fn eval_call(&mut self, name: &str, args: &[Expr]) -> Result<RValue, RuntimeError> {
        if name == "printf" {
            return self.eval_printf(args);
        }
        if name == "malloc" {
            // Model malloc as allocating a 1-cell int heap array and returning
            // a pointer to cell 0. A richer model can size this by the arg.
            let id = self.fresh_heap_id("heap");
            self.heap.insert(
                id.clone(),
                HeapArray { element_type: BaseType::Int, cells: vec![Scalar::Int(0)] },
            );
            return Ok(RValue::Pointer(Some(Location::HeapCell { id, index: 0 })));
        }
        if name == "free" {
            // No-op in the model; keep the object so the trace stays readable.
            return Ok(RValue::Void);
        }

        let func = *self.functions.get(name).ok_or(RuntimeError {
            message: format!("call to unknown function '{}'", name),
            line: 0,
        })?;

        let mut evaled = Vec::new();
        for a in args {
            evaled.push(self.eval_expr(a)?);
        }
        self.call_function(func, evaled, 0)
    }

    fn eval_printf(&mut self, args: &[Expr]) -> Result<RValue, RuntimeError> {
        if args.is_empty() {
            return Ok(RValue::Scalar(Scalar::Int(0)));
        }
        let fmt = match &args[0] {
            Expr::StrLit(s) => s.clone(),
            _ => String::new(),
        };
        let mut out = String::new();
        let mut arg_idx = 1;
        let chars: Vec<char> = fmt.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] == '%' && i + 1 < chars.len() {
                let spec = chars[i + 1];
                i += 2;
                if spec == '%' {
                    out.push('%');
                    continue;
                }
                let val = if arg_idx < args.len() {
                    let v = self.eval_expr(&args[arg_idx])?;
                    arg_idx += 1;
                    v
                } else {
                    RValue::Scalar(Scalar::Int(0))
                };
                match spec {
                    'd' | 'i' | 'l' => out.push_str(&scalar_from(val).as_i64().to_string()),
                    'f' | 'g' => out.push_str(&format!("{}", scalar_from(val).as_f64())),
                    'c' => {
                        let code = scalar_from(val).as_i64();
                        if let Some(c) = char::from_u32(code as u32) {
                            out.push(c);
                        }
                    }
                    's' => out.push_str("(str)"),
                    'p' => out.push_str("(ptr)"),
                    _ => {
                        out.push('%');
                        out.push(spec);
                    }
                }
            } else {
                out.push(chars[i]);
                i += 1;
            }
        }
        self.stdout.push_str(&out);
        Ok(RValue::Scalar(Scalar::Int(out.len() as i64)))
    }

    // ---- lvalues / locations ----------------------------------------------

    fn lvalue_of(&mut self, expr: &Expr) -> Result<Location, RuntimeError> {
        match expr {
            Expr::Ident(name) => {
                let frame = self.find_var_frame(name).ok_or(RuntimeError {
                    message: format!("use of undeclared variable '{}'", name),
                    line: 0,
                })?;
                Ok(Location::Local { frame, name: name.clone() })
            }
            Expr::Index(base, idx) => self.lvalue_of_index(base, idx),
            Expr::Unary(UnOp::Deref, inner) => {
                let v = self.eval_expr(inner)?;
                match v {
                    RValue::Pointer(Some(loc)) => Ok(loc),
                    _ => Err(RuntimeError {
                        message: "cannot assign through a null/invalid pointer".into(),
                        line: 0,
                    }),
                }
            }
            _ => Err(RuntimeError {
                message: "invalid assignment target".into(),
                line: 0,
            }),
        }
    }

    fn lvalue_of_index(&mut self, base: &Expr, idx: &Expr) -> Result<Location, RuntimeError> {
        let index = self.eval_scalar(idx)?.as_i64();
        if index < 0 {
            return Err(RuntimeError {
                message: "negative array index".into(),
                line: 0,
            });
        }
        // The base must resolve to an array/heap block.
        let id = match base {
            Expr::Ident(name) => {
                let frame = self.find_var_frame(name).ok_or(RuntimeError {
                    message: format!("use of undeclared variable '{}'", name),
                    line: 0,
                })?;
                match self.frames[frame].slots.get(name) {
                    Some(Slot::ArrayRef { id, .. }) => id.clone(),
                    Some(Slot::Pointer(Some(Location::HeapCell { id, .. }))) => id.clone(),
                    _ => {
                        return Err(RuntimeError {
                            message: format!("'{}' is not an array or pointer", name),
                            line: 0,
                        })
                    }
                }
            }
            _ => {
                let v = self.eval_expr(base)?;
                match v {
                    RValue::Pointer(Some(Location::HeapCell { id, .. })) => id,
                    _ => {
                        return Err(RuntimeError {
                            message: "indexing a non-array expression".into(),
                            line: 0,
                        })
                    }
                }
            }
        };

        let len = self.heap.get(&id).map(|a| a.cells.len()).unwrap_or(0);
        if (index as usize) >= len {
            return Err(RuntimeError {
                message: format!("array index {} out of bounds (len {})", index, len),
                line: 0,
            });
        }
        Ok(Location::HeapCell { id, index: index as usize })
    }

    fn read_location(&mut self, loc: &Location) -> Result<RValue, RuntimeError> {
        match loc {
            Location::Local { frame, name } => match self.frames[*frame].slots.get(name) {
                Some(Slot::Scalar(s)) => Ok(RValue::Scalar(s.clone())),
                Some(Slot::Pointer(p)) => Ok(RValue::Pointer(p.clone())),
                Some(Slot::ArrayRef { id, .. }) => {
                    Ok(RValue::Pointer(Some(Location::HeapCell { id: id.clone(), index: 0 })))
                }
                None => Err(RuntimeError {
                    message: format!("variable '{}' not found", name),
                    line: 0,
                }),
            },
            Location::HeapCell { id, index } => {
                let arr = self.heap.get(id).ok_or(RuntimeError {
                    message: "dangling heap reference".into(),
                    line: 0,
                })?;
                Ok(RValue::Scalar(arr.cells[*index].clone()))
            }
        }
    }

    fn write_location(&mut self, loc: &Location, value: RValue) -> Result<(), RuntimeError> {
        match loc {
            Location::Local { frame, name } => {
                let existing = self.frames[*frame].slots.get(name).cloned();
                let new_slot = match (existing, value) {
                    (Some(Slot::Pointer(_)), RValue::Pointer(p)) => Slot::Pointer(p),
                    (_, RValue::Pointer(p)) => Slot::Pointer(p),
                    (Some(Slot::Scalar(old)), RValue::Scalar(s)) => {
                        // Preserve the slot's scalar kind where sensible.
                        Slot::Scalar(coerce_to_kind(s, &old))
                    }
                    (_, RValue::Scalar(s)) => Slot::Scalar(s),
                    (Some(prev), RValue::Void) => prev,
                    (None, RValue::Void) => Slot::Scalar(Scalar::Int(0)),
                };
                self.frames[*frame].slots.insert(name.clone(), new_slot);
                Ok(())
            }
            Location::HeapCell { id, index } => {
                let arr = self.heap.get_mut(id).ok_or(RuntimeError {
                    message: "write to dangling heap reference".into(),
                    line: 0,
                })?;
                let elem_kind = arr.element_type.clone();
                let s = match value {
                    RValue::Scalar(s) => coerce_scalar(s, &elem_kind),
                    _ => default_scalar(&elem_kind),
                };
                arr.cells[*index] = s;
                Ok(())
            }
        }
    }

    fn read_ident(&mut self, name: &str) -> Result<RValue, RuntimeError> {
        let frame = self.find_var_frame(name).ok_or(RuntimeError {
            message: format!("use of undeclared variable '{}'", name),
            line: 0,
        })?;
        self.read_location(&Location::Local { frame, name: name.to_string() })
    }

    /// Find the frame index that declares `name`, searching the current frame
    /// only (C has no closures; globals are not modeled here).
    fn find_var_frame(&self, name: &str) -> Option<usize> {
        let top = self.frames.len().checked_sub(1)?;
        if self.frames[top].slots.contains_key(name) {
            Some(top)
        } else {
            None
        }
    }

    // ---- snapshotting -----------------------------------------------------

    fn snapshot(&mut self, line: Option<usize>, note: Option<String>) {
        let step = self.states.len();

        // Build stack frames for the trace.
        let mut stack = Vec::new();
        let top = self.frames.len().saturating_sub(1);
        for (fi, frame) in self.frames.iter().enumerate() {
            let mut variables = Vec::new();
            for vname in &frame.order {
                let slot = &frame.slots[vname];
                let declared = frame.declared.get(vname).map(|t| t.display());
                let tvalue = match slot {
                    Slot::Scalar(s) => TValue::primitive(s.display(), s.type_name()),
                    Slot::Pointer(p) => TValue::reference(location_to_heap_id(p)),
                    Slot::ArrayRef { id, .. } => TValue::reference(Some(id.clone())),
                };
                variables.push(TVariable {
                    name: vname.clone(),
                    value: tvalue,
                    declared_type: declared,
                });
            }
            stack.push(StackFrame {
                id: format!("frame_{}_{}", fi, frame.function_name),
                function_name: frame.function_name.clone(),
                variables,
                is_active: Some(fi == top),
            });
        }

        // Build heap objects for the trace.
        let mut heap: BTreeMap<String, HeapObject> = BTreeMap::new();
        for (id, arr) in &self.heap {
            let elements = arr
                .cells
                .iter()
                .map(|s| TValue::primitive(s.display(), s.type_name()))
                .collect();
            heap.insert(
                id.clone(),
                HeapObject::Array {
                    id: id.clone(),
                    element_type: Some(base_type_name(&arr.element_type).to_string()),
                    elements,
                },
            );
        }

        self.states.push(ProgramState {
            step,
            line,
            stack,
            heap,
            note,
            stdout: if self.stdout.is_empty() {
                None
            } else {
                Some(self.stdout.clone())
            },
        });
    }

    #[allow(dead_code)]
    fn program(&self) -> &Program {
        self.program
    }
}

// ---- free helpers ---------------------------------------------------------

fn bool_i(b: bool) -> i64 {
    if b {
        1
    } else {
        0
    }
}

fn scalar_from(v: RValue) -> Scalar {
    match v {
        RValue::Scalar(s) => s,
        _ => Scalar::Int(0),
    }
}

/// For a pointer location, return the heap id the arrow should point at (array
/// cell targets point at the containing object). Local targets are shown as a
/// pointer to that frame's variable, which the current trace model renders as
/// a generic reference; we surface heap targets precisely.
fn location_to_heap_id(p: &Option<Location>) -> Option<String> {
    match p {
        Some(Location::HeapCell { id, .. }) => Some(id.clone()),
        Some(Location::Local { .. }) => None,
        None => None,
    }
}

fn default_scalar(base: &BaseType) -> Scalar {
    match base {
        BaseType::Double | BaseType::Float => Scalar::Double(0.0),
        BaseType::Char => Scalar::Char('\0'),
        _ => Scalar::Int(0),
    }
}

fn coerce_scalar(s: Scalar, base: &BaseType) -> Scalar {
    match base {
        BaseType::Double | BaseType::Float => Scalar::Double(s.as_f64()),
        BaseType::Char => Scalar::Char(char::from_u32((s.as_i64() & 0xff) as u32).unwrap_or('\0')),
        _ => Scalar::Int(s.as_i64()),
    }
}

fn coerce_to_kind(s: Scalar, like: &Scalar) -> Scalar {
    match like {
        Scalar::Double(_) => Scalar::Double(s.as_f64()),
        Scalar::Char(_) => {
            char::from_u32((s.as_i64() & 0xff) as u32).map(Scalar::Char).unwrap_or(Scalar::Int(s.as_i64()))
        }
        Scalar::Int(_) => Scalar::Int(s.as_i64()),
    }
}

fn base_type_name(base: &BaseType) -> &'static str {
    match base {
        BaseType::Int => "int",
        BaseType::Char => "char",
        BaseType::Double => "double",
        BaseType::Float => "float",
        BaseType::Long => "long",
        BaseType::Void => "void",
    }
}

fn stmt_line(stmt: &Stmt) -> usize {
    match stmt {
        Stmt::VarDecl { line, .. } => *line,
        Stmt::ExprStmt(_, line) => *line,
        Stmt::If { line, .. } => *line,
        Stmt::While { line, .. } => *line,
        Stmt::For { line, .. } => *line,
        Stmt::Return(_, line) => *line,
        Stmt::Break(line) => *line,
        Stmt::Continue(line) => *line,
        Stmt::Block(_) => 0,
    }
}

//! C language support: lex -> parse -> interpret -> ExecutionTrace.

pub mod ast;
pub mod interp;
pub mod lexer;
pub mod parser;

use crate::trace::ExecutionTrace;

/// A user-facing error from running C code, with an optional source line.
#[derive(Debug, Clone)]
pub struct CError {
    /// "lex" | "parse" | "runtime".
    pub stage: &'static str,
    pub message: String,
    pub line: Option<usize>,
}

/// Lex, parse, and interpret a C program, producing an execution trace.
pub fn run(source: &str) -> Result<ExecutionTrace, CError> {
    let tokens = lexer::lex(source).map_err(|e| CError {
        stage: "lex",
        message: e.message,
        line: Some(e.line),
    })?;

    let mut parser = parser::Parser::new(tokens);
    let program = parser.parse_program().map_err(|e| CError {
        stage: "parse",
        message: e.message,
        line: Some(e.line),
    })?;

    let interp = interp::Interp::new(&program);
    interp.run().map_err(|e| CError {
        stage: "runtime",
        message: e.message,
        line: if e.line == 0 { None } else { Some(e.line) },
    })
}

//! CodeTutor backend HTTP server.
//!
//! Exposes `POST /api/run` which takes `{ language, code }` and returns an
//! execution trace for the visualizer (or structured errors for the alert
//! panel). Only C is implemented here; other languages are handled by
//! teammates and currently return a "not implemented" response.

mod c;
mod trace;

use axum::{
    extract::Json,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Router,
};
use serde::{Deserialize, Serialize};
use tower_http::cors::{Any, CorsLayer};

#[derive(Debug, Deserialize)]
struct RunRequest {
    language: String,
    code: String,
}

/// A problem surfaced to the frontend AlertPanel.
#[derive(Debug, Serialize)]
struct ApiError {
    severity: String,
    message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    line: Option<usize>,
    stage: String,
}

#[derive(Debug, Serialize)]
#[serde(untagged)]
enum RunResponse {
    Ok {
        ok: bool,
        trace: trace::ExecutionTrace,
    },
    Err {
        ok: bool,
        errors: Vec<ApiError>,
    },
}

#[tokio::main]
async fn main() {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    let app = Router::new()
        .route("/api/health", get(health))
        .route("/api/run", post(run_handler))
        .layer(cors);

    let addr = "127.0.0.1:8080";
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind address");
    println!("CodeTutor backend listening on http://{addr}");
    axum::serve(listener, app)
        .await
        .expect("server error");
}

async fn health() -> &'static str {
    "ok"
}

async fn run_handler(Json(req): Json<RunRequest>) -> impl IntoResponse {
    match req.language.as_str() {
        "c" => match c::run(&req.code) {
            Ok(trace) => (
                StatusCode::OK,
                Json(RunResponse::Ok { ok: true, trace }),
            ),
            Err(err) => (
                StatusCode::OK,
                Json(RunResponse::Err {
                    ok: false,
                    errors: vec![ApiError {
                        severity: "error".into(),
                        message: err.message,
                        line: err.line,
                        stage: err.stage.into(),
                    }],
                }),
            ),
        },
        other => (
            StatusCode::OK,
            Json(RunResponse::Err {
                ok: false,
                errors: vec![ApiError {
                    severity: "info".into(),
                    message: format!(
                        "language '{}' is not implemented in this backend yet",
                        other
                    ),
                    line: None,
                    stage: "dispatch".into(),
                }],
            }),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_c(src: &str) -> trace::ExecutionTrace {
        c::run(src).expect("program should run")
    }

    #[test]
    fn runs_simple_loop_and_array() {
        let src = r#"
            int main(void) {
                int values[3] = {4, 5, 6};
                int sum = 0;
                for (int i = 0; i < 3; i++) {
                    sum += values[i];
                }
                return sum;
            }
        "#;
        let trace = run_c(src);
        assert!(!trace.states.is_empty());
        // The final state should have a frame with sum = 15.
        let last = trace.states.last().unwrap();
        let main_frame = last.stack.last().unwrap();
        let sum = main_frame
            .variables
            .iter()
            .find(|v| v.name == "sum")
            .expect("sum var present");
        if let trace::Value::Primitive { display, .. } = &sum.value {
            assert_eq!(display, "15");
        } else {
            panic!("sum should be a primitive");
        }
    }

    #[test]
    fn pointer_and_deref() {
        let src = r#"
            int main(void) {
                int x = 7;
                int* p = &x;
                *p = 42;
                return x;
            }
        "#;
        let trace = run_c(src);
        let last = trace.states.last().unwrap();
        let main_frame = last.stack.last().unwrap();
        let x = main_frame.variables.iter().find(|v| v.name == "x").unwrap();
        if let trace::Value::Primitive { display, .. } = &x.value {
            assert_eq!(display, "42");
        } else {
            panic!("x should be a primitive");
        }
    }

    #[test]
    fn reports_division_by_zero() {
        let src = r#"
            int main(void) {
                int a = 1;
                int b = 0;
                int c = a / b;
                return c;
            }
        "#;
        let err = c::run(src).unwrap_err();
        assert_eq!(err.stage, "runtime");
        assert!(err.message.contains("division by zero"));
    }
}

