// Client for the CodeTutor Rust backend.
//
// The backend exposes POST /api/run and responds with either:
//   { ok: true,  trace: ExecutionTrace }
//   { ok: false, errors: ApiError[] }
// (It returns HTTP 200 even for program errors; transport/5xx failures are
// surfaced separately as a synthesized error.)

import type { ExecutionTrace } from "./components/visualization/trace";
import type { Language } from "./types";

/** Base URL of the backend. Overridable via Vite env for deployment. */
const API_BASE: string =
  (import.meta.env.VITE_API_BASE as string | undefined) ??
  "http://127.0.0.1:8080";

/** A problem reported by the backend (mirrors Rust `ApiError`). */
export interface ApiError {
  severity: "error" | "warning" | "info";
  message: string;
  line?: number;
  stage: string;
}

type RawRunResponse =
  | { ok: true; trace: ExecutionTrace }
  | { ok: false; errors: ApiError[] };

/** Normalized result the UI consumes. */
export type RunResult =
  | { ok: true; trace: ExecutionTrace }
  | { ok: false; errors: ApiError[] };

/**
 * Run a program through the backend. Program-level errors come back as
 * `{ ok: false, errors }`; a failure to reach the backend is turned into a
 * single error so the UI always has something to show.
 */
export async function runProgram(
  language: Language,
  code: string
): Promise<RunResult> {
  let res: Response;
  try {
    res = await fetch(`${API_BASE}/api/run`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ language, code }),
    });
  } catch {
    return {
      ok: false,
      errors: [
        {
          severity: "error",
          message:
            "Could not reach the CodeTutor backend. Is it running on " +
            `${API_BASE}? (start it with 'cargo run' in /backend)`,
          stage: "network",
        },
      ],
    };
  }

  if (!res.ok) {
    return {
      ok: false,
      errors: [
        {
          severity: "error",
          message: `Backend returned HTTP ${res.status} ${res.statusText}.`,
          stage: "http",
        },
      ],
    };
  }

  let data: RawRunResponse;
  try {
    data = (await res.json()) as RawRunResponse;
  } catch {
    return {
      ok: false,
      errors: [
        {
          severity: "error",
          message: "Backend returned a response that was not valid JSON.",
          stage: "decode",
        },
      ],
    };
  }

  return data;
}

export interface ConsolePanelProps {
  /** Program output captured from the last run (stdout). */
  output: string;
  /** True while a run is in flight. */
  running?: boolean;
  /** True once at least one run has completed (controls the empty message). */
  hasRun?: boolean;
}

/**
 * A terminal-style console shown below the editor (bottom-left). Displays the
 * program's stdout from the most recent run. Scrolls for long output.
 */
export default function ConsolePanel({
  output,
  running = false,
  hasRun = false,
}: ConsolePanelProps) {
  return (
    <div className="console">
      <div className="console__tabs">
        <span className="console__tab console__tab--active">Console</span>
        {running && <span className="console__status">running…</span>}
      </div>
      <div className="console__body">
        {output ? (
          <pre className="console__output">{output}</pre>
        ) : (
          <p className="console__empty">
            {running
              ? "Running your program…"
              : hasRun
              ? "Program produced no output."
              : "Run your program to see its output here."}
          </p>
        )}
      </div>
    </div>
  );
}

import CodeEditor from "../editor/CodeEditor";
import VisualizationPanel from "../visualization/VisualizationPanel";
import TutorPanel from "../tutor/TutorPanel";
import AlertPanel, { type Alert } from "../alerts/AlertPanel";
import ConsolePanel from "../console/ConsolePanel";
import type { Language } from "../../types";
import type { ExecutionTrace } from "../visualization/trace";

export interface WorkspaceProps {
  code: string;
  language: Language;
  alerts: Alert[];
  tutorQuestion?: string;
  running?: boolean;
  /** Trace to visualize (falls back to the sample when undefined). */
  trace?: ExecutionTrace;
  /** Program stdout from the last run. */
  consoleOutput: string;
  /** Whether a run has completed at least once. */
  hasRun: boolean;
  onCodeChange: (value: string) => void;
  onLanguageChange: (language: Language) => void;
  onRun?: () => void;
}

/**
 * Top-level CodeTutor layout.
 *   Left column:  code editor (top) + console (bottom).
 *   Right column: visualizer + tutor + problems.
 */
export default function Workspace({
  code,
  language,
  alerts,
  tutorQuestion,
  running,
  trace,
  consoleOutput,
  hasRun,
  onCodeChange,
  onLanguageChange,
  onRun,
}: WorkspaceProps) {
  return (
    <div className="workspace">
      <section className="workspace__left">
        <div className="workspace__editor">
          <CodeEditor
            value={code}
            language={language}
            onChange={onCodeChange}
            onLanguageChange={onLanguageChange}
            onRun={onRun}
            running={running}
          />
        </div>
        <div className="workspace__console">
          <ConsolePanel
            output={consoleOutput}
            running={running}
            hasRun={hasRun}
          />
        </div>
      </section>

      <section className="workspace__right">
        <VisualizationPanel code={code} language={language} trace={trace} />
        <TutorPanel question={tutorQuestion} />
        <AlertPanel alerts={alerts} />
      </section>
    </div>
  );
}

import { useState } from "react";
import Workspace from "./components/layout/Workspace";
import type { Alert } from "./components/alerts/AlertPanel";
import type { ExecutionTrace } from "./components/visualization/trace";
import { runProgram } from "./api";
import { type Language, STARTER_CODE } from "./types";

/** Pull the full stdout from a trace (its last state holds the complete run). */
function stdoutOf(trace: ExecutionTrace): string {
  for (let i = trace.states.length - 1; i >= 0; i--) {
    const out = trace.states[i].stdout;
    if (out !== undefined) return out;
  }
  return "";
}

export default function App() {
  const [language, setLanguage] = useState<Language>("c");
  const [code, setCode] = useState<string>(STARTER_CODE.c);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [tutorQuestion] = useState<string | undefined>(undefined);
  const [running, setRunning] = useState(false);
  const [trace, setTrace] = useState<ExecutionTrace | undefined>(undefined);
  const [consoleOutput, setConsoleOutput] = useState<string>("");
  const [hasRun, setHasRun] = useState(false);

  const handleLanguageChange = (next: Language) => {
    setLanguage(next);
    setCode(STARTER_CODE[next]);
    // Reset run artifacts when switching languages.
    setTrace(undefined);
    setAlerts([]);
    setConsoleOutput("");
    setHasRun(false);
  };

  const handleRun = async () => {
    setRunning(true);
    setAlerts([]);
    try {
      const result = await runProgram(language, code);
      if (result.ok) {
        setTrace(result.trace);
        setConsoleOutput(stdoutOf(result.trace));
      } else {
        // Keep the previous trace; surface problems and clear console.
        setConsoleOutput("");
        setAlerts(
          result.errors.map((e, i) => ({
            id: `err-${i}`,
            severity: e.severity,
            message:
              e.stage && e.stage !== "runtime"
                ? `[${e.stage}] ${e.message}`
                : e.message,
            line: e.line,
          }))
        );
      }
    } finally {
      setRunning(false);
      setHasRun(true);
    }
  };

  return (
    <div className="app">
      <header className="app__header">
        <h1 className="app__brand">CodeTutor</h1>
        <p className="app__tagline">
          Write code, watch it come to life, and learn as you go.
        </p>
      </header>

      <main className="app__main">
        <Workspace
          code={code}
          language={language}
          alerts={alerts}
          tutorQuestion={tutorQuestion}
          running={running}
          trace={trace}
          consoleOutput={consoleOutput}
          hasRun={hasRun}
          onCodeChange={setCode}
          onLanguageChange={handleLanguageChange}
          onRun={handleRun}
        />
      </main>
    </div>
  );
}

