args.newStr:
export function useStepper(trace: ExecutionTrace): Stepper {
  const states = trace.states;
  const total = states.length;

  const [step, setStep] = useState(0);
  const [playing, setPlaying] = useState(false);
  // Default to 1x (1.5s per state) so learners can follow each change.
  const [speedMs, setSpeedMs] = useState(1500);

  // When a NEW trace arrives (e.g. the user ran their program), jump to the
  // final state so they see the finished result first, then can step BACK
  // through execution to understand how it got there. We detect "new trace"
  // by reference identity and skip the very first render so the initial
  // (sample) trace still opens at the start.
  const prevTraceRef = useRef<ExecutionTrace | null>(null);
  useEffect(() => {
    if (prevTraceRef.current !== null && prevTraceRef.current !== trace) {
      setPlaying(false);
      setStep(Math.max(0, trace.states.length - 1));
    }
    prevTraceRef.current = trace;
  }, [trace]);

  // Keep step in range if the trace shrinks (e.g. a new run).
  const clamped = Math.min(step, Math.max(0, total - 1));

