        op
    } else {
        // sizeof <unary-expr>, e.g. `sizeof *node`.
        Some(Box::new(self.parse_unary()?))
    };
    Ok(Expr::Sizeof(operand))
}

Expr::Null => Ok(RValue::Pointer(None)),
Expr::Sizeof(operand) => {
    Ok(RValue::Scalar(Scalar::Int(self.sizeof_units(operand))))
}

