fn eval_scalar(&mut self, expr: &Expr) -> Result<Scalar, RuntimeError> {
    match self.eval_expr(expr)? {
        RValue::Scalar(s) => Ok(s),
        RValue::Pointer(_) => Ok(Scalar::Int(0)),
        RValue::Void => Ok(Scalar::Int(0)),
    }
