fn parse_var_decl(&mut self) -> PResult<Stmt> {
    let line = self.line();
    let ty = self.parse_type()?;

    // One or more comma-separated declarators share the base type, e.g.
    // `int a, b, c;` or `int x = 1, y = 2;`. Each becomes its own VarDecl;
    // multiple are wrapped in a Block (the interpreter runs it inline).
    let mut decls: Vec<Stmt> = Vec::new();
    loop {
        decls.push(self.parse_one_declarator(&ty, line)?);
        if !self.match_tok(&Tok::Comma) {
            break;
        }
    }
    self.eat(&Tok::Semicolon)?;

    if decls.len() == 1 {
        Ok(decls.pop().unwrap())
    } else {
        Ok(Stmt::Block(decls))
    }
}

/// Parse a single declarator (name, optional `[len]`, optional `= init`)
/// for an already-parsed base type. Does NOT consume a trailing `,` or `;`.
fn parse_one_declarator(&mut self, ty: &CType, line: usize) -> PResult<Stmt> {
    let name = self.expect_ident()?;

    // Array declaration: name[len]
    let mut array_len = None;
    if self.match_tok(&Tok::LBracket) {
        if let Tok::Int(n) = self.peek().clone() {
            self.advance();
            array_len = Some(n as usize);
        } else {
            array_len = Some(0); // size inferred from initializer
        }
        self.eat(&Tok::RBracket)?;
    }

    let mut init = None;
    let mut array_init = None;
    if self.match_tok(&Tok::Assign) {
        if self.check(&Tok::LBrace) {
            // Array initializer list { a, b, c }
            self.advance();
            let mut elems = Vec::new();
            if !self.check(&Tok::RBrace) {
                loop {
                    elems.push(self.parse_expr()?);
                    if !self.match_tok(&Tok::Comma) {
                        break;
                    }
                    if self.check(&Tok::RBrace) {
                        break;
                    }
                }
            }
            self.eat(&Tok::RBrace)?;
            if array_len.is_none() {
                array_len = Some(elems.len());
            }
            array_init = Some(elems);
        } else {
            init = Some(self.parse_expr()?);
        }
    }

    Ok(Stmt::VarDecl {
        ty: ty.clone(),
        name,
        array_len,
        init,
        array_init,
        line,
    })
}

